me","type":"string","secret":false},{"name":"phone","type":"string","secret":false},{"name":"address","type":"string","secret":false},{"name":"aadhaar_number","type":"string","secret":false},{"name":"police_verification","type":"boolean","secret":false},{"name":"police_verification_details","type":"string","secret":false},{"name":"role_id","type":"string","secret":false}]},"multipart":[],"description":"Create a user account. email, password and phone are always mandatory.\n\nEMPLOYEE ONBOARDING (any staff role — doctor/nurse/receptionist/…): when role_id is a non-patient role, these are ALSO mandatory:\n  - first_name (Name)\n  - address\n  - aadhaar_number (12 digits; spaces/hyphens tolerated)\n  - police_verification (true/false)\n\nWhen police_verification is true, police_verification_details is ALSO mandatory (free text, max 500 chars — certificate number / police station / clearance date). It is stored as null when police_verification is false or not set.\n\nPatient-role accounts skip the onboarding fields.\nFor doctors, follow up with Doctors → Create Doctor Profile (qualification mandatory there)."},{"id":"op_074","group":"Users","title":"Get User","method":"GET","path":"/users/{{user_id}}","query":[],"parameters":["user_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_075","group":"Users","title":"Update User","method":"PUT","path":"/users/{{user_id}}","query":[],"parameters":["user_id"],"body":{"type":"object","fields":[{"name":"first_name","type":"string","secret":false},{"name":"phone","type":"string","secret":false},{"name":"police_verification","type":"boolean","secret":false},{"name":"police_verification_details","type":"string","secret":false}]},"multipart":[],"description":"Admin-only fields: phone, aadhaar_number, police_verification, police_verification_details, is_active, force_password_reset.\n\nSetting police_verification true requires police_verification_details — either sent in the same request or already stored. Setting it to false/null clears the stored details."},{"id":"op_076","group":"Users","title":"Delete User (deactivate)","method":"DELETE","path":"/users/{{user_id}}","query":[],"parameters":["user_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_077","group":"Users","title":"Get User Hospitals","method":"GET","path":"/users/{{user_id}}/hospitals","query":[],"parameters":["user_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_078","group":"Hospitals","title":"List Hospitals","method":"GET","path":"/hospitals","query":["page","search"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_079","group":"Hospitals","title":"Hospitals Dropdown","method":"GET","path":"/hospitals/dropdown","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_080","group":"Hospitals","title":"Create Hospital (superadmin)","method":"POST","path":"/hospitals","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"name","type":"string","secret":false},{"name":"code","type":"string","secret":false},{"name":"city","type":"string","secret":false},{"name":"state","type":"string","secret":false},{"name":"country","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_081","group":"Hospitals","title":"Get Hospital","method":"GET","path":"/hospitals/{{hospital_id}}","query":[],"parameters":["hospital_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_082","group":"Hospitals","title":"Update Hospital","method":"PUT","path":"/hospitals/{{hospital_id}}","query":[],"parameters":["hospital_id"],"body":{"type":"object","fields":[{"name":"name","type":"string","secret":false},{"name":"phone","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_083","group":"Hospitals","title":"Delete Hospital","method":"DELETE","path":"/hospitals/{{hospital_id}}","query":[],"parameters":["hospital_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_084","group":"Hospitals","title":"List Hospital Users","method":"GET","path":"/hospitals/{{hospital_id}}/users","query":[],"parameters":["hospital_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_085","group":"Hospitals","title":"Add User to Hospital","method":"POST","path":"/hospitals/{{hospital_id}}/users","query":[],"parameters":["hospital_id"],"body":{"type":"object","fields":[{"name":"user_id","type":"string","secret":false},{"name":"role_id","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_086","group":"Hospitals","title":"Update Hospital User","method":"PUT","path":"/hospitals/{{hospital_id}}/users/{{membership_id}}","query":[],"parameters":["hospital_id","membership_id"],"body":{"type":"object","fields":[{"name":"role_id","type":"string","secret":false},{"name":"is_active","type":"boolean","secret":false}]},"multipart":[],"description":""},{"id":"op_087","group":"Hospitals","title":"Remove User from Hospital","method":"DELETE","path":"/hospitals/{{hospital_id}}/users/{{membership_id}}","query":[],"parameters":["hospital_id","membership_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_088","group":"Organisations","title":"List Organisations","method":"GET","path":"/organizations","query":["page","search"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Superadmins see every organisation; an org member sees only their own. Others get an empty list - the existence of other tenants is never leaked."},{"id":"op_089","group":"Organisations","title":"Create Organisation","method":"POST","path":"/organizations","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"name","type":"string","secret":false},{"name":"code","type":"string","secret":false},{"name":"registration_number","type":"string","secret":false},{"name":"email","type":"string","secret":false},{"name":"phone","type":"string","secret":false},{"name":"city","type":"string","secret":false},{"name":"state","type":"string","secret":false}]},"multipart":[],"description":"Superadmin only. code is auto-generated (ORG-001, ORG-002, ...) when omitted."},{"id":"op_090","group":"Organisations","title":"Get Organisation","method":"GET","path":"/organizations/{{organization_id}}","query":[],"parameters":["organization_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Includes the group hospital list."},{"id":"op_091","group":"Organisations","title":"Update Organisation","method":"PUT","path":"/organizations/{{organization_id}}","query":[],"parameters":["organization_id"],"body":{"type":"object","fields":[{"name":"phone","type":"string","secret":false},{"name":"city","type":"string","secret":false}]},"multipart":[],"description":"org_admin or superadmin. Only a superadmin may set is_active on a whole organisation."},{"id":"op_092","group":"Organisations","title":"Hospitals in the Organisation","method":"GET","path":"/organizations/{{organization_id}}/hospitals","query":["include_inactive"],"parameters":["organization_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"The head office site list."},{"id":"op_093","group":"Organisations","title":"Attach Hospital to Organisation","method":"POST","path":"/organizations/{{organization_id}}/hospitals/{{hospital_id}}","query":[],"parameters":["organization_id","hospital_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Superadmin only. Moving a hospital between groups changes who can see its data, so a group admin cannot do it themselves."},{"id":"op_094","group":"Organisations","title":"Detach Hospital from Organisation","method":"DELETE","path":"/organizations/{{organization_id}}/hospitals/{{hospital_id}}","query":[],"parameters":["organization_id","hospital_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"The hospital becomes standalone again."},{"id":"op_095","group":"Organisations","title":"Organisation Members","method":"GET","path":"/organizations/{{organization_id}}/members","query":[],"parameters":["organization_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"People holding an organisation-level role here."},{"id":"op_096","group":"Organisations","title":"Add / Update Member","method":"POST","path":"/organizations/{{organization_id}}/members","query":[],"parameters":["organization_id"],"body":{"type":"object","fields":[{"name":"user_id","type":"string","secret":false},{"name":"role","type":"string","secret":false}]},"multipart":[],"description":"Grant a user an organisation-level role: org_admin or org_viewer.\n\nrole is a fixed CONSTANT, not a role_id from the roles master table - see Lookups -> Organisation Roles. Hospital memberships use role_id from that master; organisation memberships do not, because that table scopes a user to ONE hospital.\n\nThey keep any hospital memberships they already have. Posting again for the same user updates their role.\n\n409 if the user already belongs to a different organisation - belonging to two would make \"their organisation\" ambiguous at login and in every scoped query."},{"id":"op_097","group":"Organisations","title":"Remove Member","method":"DELETE","path":"/organizations/{{organization_id}}/members/{{user_id}}","query":[],"parameters":["organization_id","user_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Revoke organisation-level access. Takes effect on their next token refresh, because refresh re-reads membership rather than trusting the old token.\n\nRefused (409) if this is the only org_admin - a group is never left with nobody who can administer it. You cannot remove your own access."},{"id":"op_098","group":"Organisations","title":"My Scope (what am I allowed to see?)","method":"GET","path":"/organizations/my-scope","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"The resolved data reach of the current token - what the FE needs to decide whether to show a hospital switcher and an \"all hospitals\" option.\n\nReturns { scope, org_role, hospital_id, organization, hospitals[], can_view_all_hospitals }.\n\nscope is one of:\n  platform     - superadmin; every hospital\n  organisation - every hospital in the group\n  hospital     - exactly one\n  none         - no hospital context"},{"id":"op_099","group":"Roles","title":"List Roles","method":"GET","path":"/roles","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_100","group":"Roles","title":"Roles Dropdown","method":"GET","path":"/roles/dropdown","query":["exclude_superadmin"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_101","group":"Roles","title":"Get Role","method":"GET","path":"/roles/{{role_id}}","query":[],"parameters":["role_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_102","group":"Roles","title":"Create Role","method":"POST","path":"/roles","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"name","type":"string","secret":false},{"name":"slug","type":"string","secret":false},{"name":"description","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_103","group":"Roles","title":"Update Role","method":"PUT","path":"/roles/{{role_id}}","query":[],"parameters":["role_id"],"body":{"type":"object","fields":[{"name":"description","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_104","group":"Roles","title":"Delete Role","method":"DELETE","path":"/roles/{{role_id}}","query":[],"parameters":["role_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_105","group":"Menu","title":"My Menu","method":"GET","path":"/menu/my-menu","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Menu tree for the current user, scoped by their role."},{"id":"op_106","group":"Menu","title":"List Menu Items (superadmin)","method":"GET","path":"/menu","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_107","group":"Menu","title":"Create Menu Item","method":"POST","path":"/menu","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"name","type":"string","secret":false},{"name":"slug","type":"string","secret":false},{"name":"icon","type":"string","secret":false},{"name":"route_path","type":"string","secret":false},{"name":"sort_order","type":"number","secret":false}]},"multipart":[],"description":""},{"id":"op_108","group":"Menu","title":"Update Menu Item","method":"PUT","path":"/menu/{{menu_item_id}}","query":[],"parameters":["menu_item_id"],"body":{"type":"object","fields":[{"name":"sort_order","type":"number","secret":false}]},"multipart":[],"description":""},{"id":"op_109","group":"Menu","title":"Delete Menu Item","method":"DELETE","path":"/menu/{{menu_item_id}}","query":[],"parameters":["menu_item_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_110","group":"Menu","title":"Get Role Menu Access","method":"GET","path":"/menu/role/{{role_id}}","query":[],"parameters":["role_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_111","group":"Menu","title":"Set Role Menu Access (bulk replace)","method":"PUT","path":"/menu/role/{{role_id}}","query":[],"parameters":["role_id"],"body":{"type":"object","fields":[{"name":"accesses","type":"array","item":{"type":"object","fields":[{"name":"menu_item_id","type":"string","secret":false},{"name":"can_view","type":"boolean","secret":false},{"name":"can_create","type":"boolean","secret":false},{"name":"can_edit","type":"boolean","secret":false},{"name":"can_delete","type":"boolean","secret":false}]}}]},"multipart":[],"description":""},{"id":"op_112","group":"Departments","title":"List Departments","method":"GET","path":"/departments","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_113","group":"Departments","title":"Departments Dropdown","method":"GET","path":"/departments/dropdown","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_114","group":"Departments","title":"Create Department","method":"POST","path":"/departments","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"name","type":"string","secret":false},{"name":"code","type":"string","secret":false},{"name":"description","type":"string","secret":false},{"name":"color","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_115","group":"Departments","title":"Get Department","method":"GET","path":"/departments/{{department_id}}","query":[],"parameters":["department_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_116","group":"Departments","title":"Update Department","method":"PUT","path":"/departments/{{department_id}}","query":[],"parameters":["department_id"],"body":{"type":"object","fields":[{"name":"description","type":"string","secret":false},{"name":"head_doctor_id","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_117","group":"Departments","title":"Delete Department","method":"DELETE","path":"/departments/{{department_id}}","query":[],"parameters":["department_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_118","group":"Departments","title":"List Department Doctors","method":"GET","path":"/departments/{{department_id}}/doctors","query":[],"parameters":["department_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_119","group":"Departments","title":"Assign Doctor to Department","method":"POST","path":"/departments/{{department_id}}/doctors/{{doctor_id}}","query":[],"parameters":["department_id","doctor_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_120","group":"Departments","title":"Unassign Doctor","method":"DELETE","path":"/departments/{{department_id}}/doctors/{{doctor_id}}","query":[],"parameters":["department_id","doctor_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_121","group":"Doctors","title":"List Doctors","method":"GET","path":"/doctors","query":["page","specialization"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_122","group":"Doctors","title":"Doctors Dropdown","method":"GET","path":"/doctors/dropdown","query":["department_id","available_only"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_123","group":"Doctors","title":"Doctor Specializations (distinct)","method":"GET","path":"/doctors/specializations","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_124","group":"Doctors","title":"My Doctor Profile (me)","method":"GET","path":"/doctors/me","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"The logged-in doctor's own profile — resolves doctor_id for the UI without knowing it in advance.\n\nReturns the full DoctorProfile (doctor_number, specialization, department, fee, availability settings) with embedded user info.\n\n404 if the current user has no active doctor profile in the selected hospital."},{"id":"op_125","group":"Doctors","title":"Create Doctor Profile","method":"POST","path":"/doctors","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"user_id","type":"string","secret":false},{"name":"specialization","type":"string","secret":false},{"name":"qualification","type":"string","secret":false},{"name":"experience_years","type":"number","secret":false},{"name":"consultation_fee","type":"number","secret":false},{"name":"social_media_url","type":"string","secret":false},{"name":"weekly_schedule","type":"array","item":{"type":"object","fields":[{"name":"day","type":"string","secret":false},{"name":"is_available","type":"boolean","secret":false},{"name":"start_time","type":"string","secret":false},{"name":"end_time","type":"string","secret":false}]}}]},"multipart":[],"description":"Create a doctor profile for an existing hospital user with the doctor role.\n\nMandatory: user_id, qualification (e.g. \"MBBS, MD\").\n\nweekly_schedule is OPTIONAL - omit it and the doctor is seeded from the hospital's default working days and consultation window. See \"Set Doctor Schedule\" below for the full entry format.\n\nsocial_media_url is optional; a bare domain gets https:// prepended.\n\nThis endpoint ALSO accepts multipart/form-data - see the next request."},{"id":"op_126","group":"Doctors","title":"Create Doctor with Photo (multipart)","method":"POST","path":"/doctors","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[{"name":"data","type":"object","fields":[{"name":"user_id","type":"string"},{"name":"qualification","type":"string"},{"name":"specialization","type":"string"},{"name":"consultation_fee","type":"number"},{"name":"weekly_schedule","type":"array","item":{"type":"object","fields":[{"name":"day","type":"string"},{"name":"is_available","type":"boolean"},{"name":"start_time","type":"string"},{"name":"end_time","type":"string"}]}}]},{"name":"photo","type":"file"}],"description":"Create a doctor AND their photo in one call.\n\nmultipart/form-data with two parts:\n  data  - a JSON STRING of the usual create body. It is a JSON part rather than flat form fields because weekly_schedule is nested and flat fields cannot express it.\n  photo - the image file (optional)\n\nPlain application/json still works exactly as before."},{"id":"op_127","group":"Doctors","title":"Get Doctor","method":"GET","path":"/doctors/{{doctor_id}}","query":[],"parameters":["doctor_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_128","group":"Doctors","title":"Update Doctor","method":"PUT","path":"/doctors/{{doctor_id}}","query":[],"parameters":["doctor_id"],"body":{"type":"object","fields":[{"name":"consultation_fee","type":"number","secret":false},{"name":"is_available","type":"boolean","secret":false},{"name":"social_media_url","type":"string","secret":false}]},"multipart":[],"description":"Update profile fields. weekly_schedule may also be sent here and replaces the whole week.\n\navailable_days / available_from / available_to are REJECTED with a 400 - send weekly_schedule instead.\nphoto_url is not writable - use POST /doctors/<id>/photo."},{"id":"op_129","group":"Doctors","title":"Get Doctor Schedule (day-wise)","method":"GET","path":"/doctors/{{doctor_id}}/schedule","query":[],"parameters":["doctor_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"All 7 days with their own timings. Days off come back with is_available=false and null times.\n\nReturns { doctor_id, doctor_number, consultation_duration, is_available, weekly_schedule: [{day_of_week, day, is_available, start_time, end_time}] }."},{"id":"op_130","group":"Doctors","title":"Set Doctor Schedule (day-wise)","method":"PUT","path":"/doctors/{{doctor_id}}/schedule","query":[],"parameters":["doctor_id"],"body":{"type":"object","fields":[{"name":"weekly_schedule","type":"array","item":{"type":"object","fields":[{"name":"day","type":"string","secret":false},{"name":"is_available","type":"boolean","secret":false},{"name":"start_time","type":"string","secret":false},{"name":"end_time","type":"string","secret":false}]}}]},"multipart":[],"description":"Day-wise availability: each weekday carries its OWN timings instead of one span shared by every working day.\n\nEntry shape: {day_of_week | day, is_available, start_time, end_time}\n  day          - name or 3-letter abbreviation (\"Monday\", \"mon\")\n  day_of_week  - 0-6, where 0 = Monday\n  start/end    - 24h \"09:00\" or 12h \"09:00 AM\"; stored as 24h HH:MM\n\nDays left out of the list are treated as NOT available. At least one day must be available. Rejected: end_time before start_time, duplicate days, missing times on an available day, unknown day names.\n\nBREAKING - available_days / available_from / available_to are gone. Sending any of them returns 400 pointing at weekly_schedule. Doctor responses carry weekly_schedule instead."},{"id":"op_131","group":"Doctors","title":"Upload Doctor Photo","method":"POST","path":"/doctors/{{doctor_id}}/photo","query":[],"parameters":["doctor_id"],"body":{"type":"object","fields":[]},"multipart":[{"name":"photo","type":"file"}],"description":"Upload or replace a doctor photo (multipart/form-data).\n\nForm field: photo (file). \"file\" is accepted as an alias.\njpg, jpeg, png, gif or webp - max 5 MB. The bytes are decoded to confirm they really are an image, so a renamed file is rejected.\n\nReplacing a photo deletes the previous S3 object only after the new key is committed. A doctor may manage their own photo; otherwise hospital_admin is required.\n\nResponds with the doctor, whose photo_url is a short-lived PRESIGNED URL (the bucket stays private), plus a has_photo boolean.\n\n503 when S3 is not configured (AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY / AWS_S3_BUCKET)."},{"id":"op_132","group":"Doctors","title":"Delete Doctor Photo","method":"DELETE","path":"/doctors/{{doctor_id}}/photo","query":[],"parameters":["doctor_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Remove the photo from S3 and clear it on the record. The row is cleared first, so a failure leaves an orphaned object rather than a dead link."},{"id":"op_133","group":"Doctors","title":"Doctor's Availability (slots on date)","method":"GET","path":"/doctors/{{doctor_id}}/availability","query":["date"],"parameters":["doctor_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Bookable slots for one date, generated from THAT weekday's hours.\n\nReturns { date, day, is_available, available_from, available_to, slots: [{time, available}] }. A day the doctor does not work returns is_available=false and an empty slot list."},{"id":"op_134","group":"Doctors","title":"Doctor's Appointments","method":"GET","path":"/doctors/{{doctor_id}}/appointments","query":[],"parameters":["doctor_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_135","group":"Patients","title":"List Patients","method":"GET","path":"/patients","query":["page","search","blood_group","gender","referral_source","insurance_provider","insurance_category","hospital_id"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Paginated patient list. Items are full patient payloads, so referral and insurance fields are included.\n\nFILTERS\n  search              - patient_number, first/last name, phone\n  blood_group, gender - exact match\n  referral_source     - how the patient reached the hospital\n  insurance_provider  - exact provider\n  insurance_category  - private | government | other; expands to the providers in that category. Uninsured patients match no category.\n  hospital_id         - organisation-wide callers only: narrow to one hospital in the group. It can NEVER widen scope - asking for a hospital you cannot reach returns an empty list, not an error.\n\nAll enum filters are validated: an unknown value returns 400 rather than silently returning nothing.\n\nA patient signed in themselves sees only their own record."},{"id":"op_136","group":"Patients","title":"Patient Search (typeahead)","method":"GET","path":"/patients/search","query":["q","limit"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_137","group":"Patients","title":"Patient Dropdown (appointments)","method":"GET","path":"/patients/dropdown","query":["module","q","doctor_id","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Role- and module-aware patient dropdown.\n\nmodule (required): appointments | prescription | laboratory | billing | calendar\nq / search: typeahead over patient_number, name, phone, email\ndoctor_id: narrow to that doctor's patients (not supported for billing)\npage: 1-based page number, default 1\nper_page: page size, default 20, max 100 (alias: limit)\nhospital_id: superadmin only\n\nScope per role — patient: own profile only; doctor: own patients for prescription / laboratory / calendar and every patient for appointments; pharmacist: patients that have prescriptions; lab_technician: patients that have lab orders; hospital_admin / nurse / receptionist / accountant: every active patient. The calendar module always returns patients that have appointments. Scopes backed by module records (appointments, prescriptions, lab orders) de-duplicate, so a patient with 40 appointments still appears once.\n\nReturns { module, scope, doctor_id, items: [{ value, label, id, patient_number, full_name, age, gender, blood_group, phone }], meta: { page, per_page, total_items, total_pages, has_next, has_prev } }.\n\nPaginated like GET /patients — for long patient lists, load page 1 and fetch page+1 while meta.has_next is true (infinite scroll / \"load more\"), or let the user type and re-query with ?q= instead of paging."},{"id":"op_138","group":"Patients","title":"Patient Dropdown (prescription)","method":"GET","path":"/patients/dropdown","query":["module","q","doctor_id","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Role- and module-aware patient dropdown.\n\nmodule (required): appointments | prescription | laboratory | billing | calendar\nq / search: typeahead over patient_number, name, phone, email\ndoctor_id: narrow to that doctor's patients (not supported for billing)\npage: 1-based page number, default 1\nper_page: page size, default 20, max 100 (alias: limit)\nhospital_id: superadmin only\n\nScope per role — patient: own profile only; doctor: own patients for prescription / laboratory / calendar and every patient for appointments; pharmacist: patients that have prescriptions; lab_technician: patients that have lab orders; hospital_admin / nurse / receptionist / accountant: every active patient. The calendar module always returns patients that have appointments. Scopes backed by module records (appointments, prescriptions, lab orders) de-duplicate, so a patient with 40 appointments still appears once.\n\nReturns { module, scope, doctor_id, items: [{ value, label, id, patient_number, full_name, age, gender, blood_group, phone }], meta: { page, per_page, total_items, total_pages, has_next, has_prev } }.\n\nPaginated like GET /patients — for long patient lists, load page 1 and fetch page+1 while meta.has_next is true (infinite scroll / \"load more\"), or let the user type and re-query with ?q= instead of paging."},{"id":"op_139","group":"Patients","title":"Patient Dropdown (laboratory)","method":"GET","path":"/patients/dropdown","query":["module","q","doctor_id","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Role- and module-aware patient dropdown.\n\nmodule (required): appointments | prescription | laboratory | billing | calendar\nq / search: typeahead over patient_number, name, phone, email\ndoctor_id: narrow to that doctor's patients (not supported for billing)\npage: 1-based page number, default 1\nper_page: page size, default 20, max 100 (alias: limit)\nhospital_id: superadmin only\n\nScope per role — patient: own profile only; doctor: own patients for prescription / laboratory / calendar and every patient for appointments; pharmacist: patients that have prescriptions; lab_technician: patients that have lab orders; hospital_admin / nurse / receptionist / accountant: every active patient. The calendar module always returns patients that have appointments. Scopes backed by module records (appointments, prescriptions, lab orders) de-duplicate, so a patient with 40 appointments still appears once.\n\nReturns { module, scope, doctor_id, items: [{ value, label, id, patient_number, full_name, age, gender, blood_group, phone }], meta: { page, per_page, total_items, total_pages, has_next, has_prev } }.\n\nPaginated like GET /patients — for long patient lists, load page 1 and fetch page+1 while meta.has_next is true (infinite scroll / \"load more\"), or let the user type and re-query with ?q= instead of paging."},{"id":"op_140","group":"Patients","title":"Patient Dropdown (billing)","method":"GET","path":"/patients/dropdown","query":["module","q","doctor_id","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Role- and module-aware patient dropdown.\n\nmodule (required): appointments | prescription | laboratory | billing | calendar\nq / search: typeahead over patient_number, name, phone, email\ndoctor_id: narrow to that doctor's patients (not supported for billing)\npage: 1-based page number, default 1\nper_page: page size, default 20, max 100 (alias: limit)\nhospital_id: superadmin only\n\nScope per role — patient: own profile only; doctor: own patients for prescription / laboratory / calendar and every patient for appointments; pharmacist: patients that have prescriptions; lab_technician: patients that have lab orders; hospital_admin / nurse / receptionist / accountant: every active patient. The calendar module always returns patients that have appointments. Scopes backed by module records (appointments, prescriptions, lab orders) de-duplicate, so a patient with 40 appointments still appears once.\n\nReturns { module, scope, doctor_id, items: [{ value, label, id, patient_number, full_name, age, gender, blood_group, phone }], meta: { page, per_page, total_items, total_pages, has_next, has_prev } }.\n\nPaginated like GET /patients — for long patient lists, load page 1 and fetch page+1 while meta.has_next is true (infinite scroll / \"load more\"), or let the user type and re-query with ?q= instead of paging."},{"id":"op_141","group":"Patients","title":"Patient Dropdown (calendar)","method":"GET","path":"/patients/dropdown","query":["module","q","doctor_id","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Role- and module-aware patient dropdown.\n\nmodule (required): appointments | prescription | laboratory | billing | calendar\nq / search: typeahead over patient_number, name, phone, email\ndoctor_id: narrow to that doctor's patients (not supported for billing)\npage: 1-based page number, default 1\nper_page: page size, default 20, max 100 (alias: limit)\nhospital_id: superadmin only\n\nScope per role — patient: own profile only; doctor: own patients for prescription / laboratory / calendar and every patient for appointments; pharmacist: patients that have prescriptions; lab_technician: patients that have lab orders; hospital_admin / nurse / receptionist / accountant: every active patient. The calendar module always returns patients that have appointments. Scopes backed by module records (appointments, prescriptions, lab orders) de-duplicate, so a patient with 40 appointments still appears once.\n\nReturns { module, scope, doctor_id, items: [{ value, label, id, patient_number, full_name, age, gender, blood_group, phone }], meta: { page, per_page, total_items, total_pages, has_next, has_prev } }.\n\nPaginated like GET /patients — for long patient lists, load page 1 and fetch page+1 while meta.has_next is true (infinite scroll / \"load more\"), or let the user type and re-query with ?q= instead of paging."},{"id":"op_142","group":"Patients","title":"Create Patient","method":"POST","path":"/patients","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"first_name","type":"string","secret":false},{"name":"last_name","type":"string","secret":false},{"name":"gender","type":"string","secret":false},{"name":"blood_group","type":"string","secret":false},{"name":"phone","type":"string","secret":false},{"name":"date_of_birth","type":"string","secret":false},{"name":"address","type":"string","secret":false},{"name":"city","type":"string","secret":false},{"name":"id_proof_type","type":"string","secret":false},{"name":"id_proof_number","type":"string","secret":false},{"name":"disease_category","type":"string","secret":false},{"name":"referral_source","type":"string","secret":false},{"name":"referral_details","type":"string","secret":false},{"name":"insurance_provider","type":"string","secret":false},{"name":"insurance_number","type":"string","secret":false},{"name":"insurance_tpa","type":"string","secret":false},{"name":"emergency_contact_name","type":"string","secret":false},{"name":"emergency_contact_phone","type":"string","secret":false}]},"multipart":[],"description":"Register a patient.\n\nMANDATORY: first_name, phone (10-digit Indian mobile), address, city (falls back to the hospital default), id_proof_type + id_proof_number, and ONE OF date_of_birth or age.\nemail is OPTIONAL for patients.\n\nAGE / DATE OF BIRTH\n  - Send date_of_birth and age is calculated automatically.\n  - Send age alone when the patient does not know their DOB (0-120).\n  - Send both and DOB wins; the age you sent is ignored.\n  - Send neither and the request is rejected.\n  The stored age is recomputed from DOB on every write, and the age in responses is always current - it never goes stale.\n\nID PROOF (see Lookups -> ID Proof Types): aadhar_card | pan_card | voter_id | passport. The number is format-validated per type (Aadhaar 12 digits, PAN ABCDE1234F, Voter ID ABC1234567, Passport A1234567) and normalized - spaces and hyphens stripped, uppercased.\n\nREFERRAL (optional, see Lookups -> Referral Sources)\n  referral_source: social_media | doctor_reference | existing_patient_reference | hospital_reference | advertisement | other\n  referral_details: free text naming WHO referred (max 255). Kept only for doctor / existing-patient / hospital / other - it is dropped for social_media and advertisement, where there is nobody to name.\n\nINSURANCE (optional, see Lookups -> Insurance Providers)\n  insurance_provider: one of 38 values, grouped private / government / other\n  insurance_provider_other: REQUIRED when provider is \"other\" (max 120); nulled for any listed insurer\n  insurance_number: policy or beneficiary card number\n  insurance_tpa: see Lookups -> Insurance TPAs\n  Clearing insurance_provider nulls the number, TPA and manual name.\n\nResponses add two READ-ONLY derived fields: insurance_category (private | government | other) and insurance_provider_name, which resolves to the display label for a listed insurer or the typed name for \"other\" - one field to render regardless of which path was used.\n\nAlso optional: disease_category (see Lookups), kyc_record_id (from the Aadhaar QR verify flow), and every other profile field."},{"id":"op_143","group":"Patients","title":"Get Patient","method":"GET","path":"/patients/{{patient_id}}","query":[],"parameters":["patient_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_144","group":"Patients","title":"Create Patient (age only, no DOB)","method":"POST","path":"/patients","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"first_name","type":"string","secret":false},{"name":"gender","type":"string","secret":false},{"name":"phone","type":"string","secret":false},{"name":"age","type":"number","secret":false},{"name":"address","type":"string","secret":false},{"name":"city","type":"string","secret":false},{"name":"id_proof_type","type":"string","secret":false},{"name":"id_proof_number","type":"string","secret":false},{"name":"referral_source","type":"string","secret":false},{"name":"insurance_provider","type":"string","secret":false},{"name":"insurance_number","type":"string","secret":false}]},"multipart":[],"description":"The common walk-in case: the patient does not know their date of birth, so age is captured directly. date_of_birth stays null and the recorded age is returned as-is.\n\nNote ayushman_bharat is a GOVERNMENT scheme - the lookup flags it is_government=true so the FE can relabel the number field to \"beneficiary ID\" rather than \"policy number\"."},{"id":"op_145","group":"Patients","title":"Create Patient (insurer not listed)","method":"POST","path":"/patients","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"first_name","type":"string","secret":false},{"name":"gender","type":"string","secret":false},{"name":"phone","type":"string","secret":false},{"name":"age","type":"number","secret":false},{"name":"address","type":"string","secret":false},{"name":"city","type":"string","secret":false},{"name":"id_proof_type","type":"string","secret":false},{"name":"id_proof_number","type":"string","secret":false},{"name":"insurance_provider","type":"string","secret":false},{"name":"insurance_provider_other","type":"string","secret":false},{"name":"insurance_number","type":"string","secret":false}]},"multipart":[],"description":"When the insurer is not in the catalogue, pick \"other\" and type the name. insurance_provider_other is REQUIRED in that case and rejected with a 400 if missing.\n\ninsurance_provider_name in the response resolves to the typed name, so reports and printouts read one field either way."},{"id":"op_146","group":"Patients","title":"Update Patient","method":"PUT","path":"/patients/{{patient_id}}","query":[],"parameters":["patient_id"],"body":{"type":"object","fields":[{"name":"phone","type":"string","secret":false},{"name":"allergies","type":"string","secret":false},{"name":"referral_source","type":"string","secret":false},{"name":"referral_details","type":"string","secret":false}]},"multipart":[],"description":"Partial update. Referral and insurance are validated as GROUPS - a partial edit is checked against the values already stored, so sending insurance_number alone still validates against the stored provider.\n\nThe DOB/age pair rule is only enforced when the request actually touches date_of_birth or age, so patients registered before the rule existed stay editable."},{"id":"op_147","group":"Patients","title":"Patient's Appointments","method":"GET","path":"/patients/{{patient_id}}/appointments","query":[],"parameters":["patient_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_148","group":"Patients","title":"Patient's Prescriptions","method":"GET","path":"/patients/{{patient_id}}/prescriptions","query":[],"parameters":["patient_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_149","group":"Patients","title":"Patient's Lab Orders","method":"GET","path":"/patients/{{patient_id}}/lab-orders","query":[],"parameters":["patient_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_150","group":"Patients","title":"Patient's Bills","method":"GET","path":"/patients/{{patient_id}}/bills","query":[],"parameters":["patient_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_151","group":"Aadhaar KYC","title":"Verify QR — V2 Secure (decimal string)","method":"POST","path":"/aadhaar/verify-qr","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"qr_data","type":"string","secret":false},{"name":"source","type":"string","secret":false}]},"multipart":[],"description":"Decode an Aadhaar V2 Secure QR.\n\nqr_data: the raw decimal string returned by html5-qrcode / jsQR / ZXing when scanning a 2018+ Aadhaar card.\n\nThe backend:\n  1. Converts the decimal string to bytes.\n  2. GZIP-decompresses.\n  3. Splits on 0xFF delimiters to extract demographic fields + JPEG photo.\n  4. Verifies UIDAI RSA-SHA256 signature (requires UIDAI_PUBLIC_CERT_FILE env var; dev returns 'unsigned').\n  5. Saves an AadhaarKYC record and returns patient_form_defaults for auto-fill.\n\nVerification status:\n  verified  — UIDAI signature matched (production).\n  unsigned  — No cert configured (dev / test).\n  invalid   — Signature failed; record rejected."},{"id":"op_152","group":"Aadhaar KYC","title":"Verify QR — V1 XML (paper letter / pre-2018)","method":"POST","path":"/aadhaar/verify-qr","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"qr_data","type":"string","secret":false},{"name":"source","type":"string","secret":false}]},"multipart":[],"description":"Decode an Aadhaar V1 QR (old paper letter / eAadhaar pre-2018).\n\nqr_data: the raw XML string returned by the QR scanner, starting with '<PrintLetterBarcodeData ...'.\n\nThe backend:\n  1. Detects the '<' prefix and routes to the V1 XML parser.\n  2. Reads uid attribute — last 4 digits used for masking; SHA-256 hash stored (full UID never persisted).\n  3. Extracts name, dob/yob, gender, address fields.\n  4. Returns verification_status = 'unsigned' (V1 has no RSA signature).\n  5. photo_base64 is always null for V1.\n\nV1 XML attributes mapped:\n  uid → masked_aadhaar / aadhaar_hash\n  name, gender, dob (or yob), co, house, street, lm, loc, vtc, subdist, dist, state, pc, po"},{"id":"op_153","group":"Aadhaar KYC","title":"Debug QR Chunks (V2 only)","method":"POST","path":"/aadhaar/debug-qr","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"qr_data","type":"string","secret":false}]},"multipart":[],"description":"DEV ONLY — returns raw 0xFF-delimited chunk breakdown of a V2 Secure QR.\nUse this to diagnose field-order mismatches between the QR_V2_FIELDS map and real cards.\n\nV1 XML QRs are not supported here (they have no binary chunks); use Verify QR instead."},{"id":"op_154","group":"Aadhaar KYC","title":"Get KYC Record","method":"GET","path":"/aadhaar/kyc/{{kyc_id}}","query":[],"parameters":["kyc_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Fetch a single AadhaarKYC record by ID (includes photo_base64 if present).\nUse the kyc_record_id returned by verify-qr."},{"id":"op_155","group":"Aadhaar KYC","title":"List KYC Records","method":"GET","path":"/aadhaar/kyc","query":["status","source","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"List KYC records for the hospital (audit screen).\n\nFilters:\n  status — verified | unsigned | invalid\n  source — qr_card | qr_pvc | qr_digital\n  page / per_page — pagination (default 20, max 100)"},{"id":"op_156","group":"Appointments","title":"List Appointments","method":"GET","path":"/appointments","query":["date","status","doctor_id"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_157","group":"Appointments","title":"Book Appointment","method":"POST","path":"/appointments","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"patient_id","type":"string","secret":false},{"name":"doctor_id","type":"string","secret":false},{"name":"date","type":"string","secret":false},{"name":"time","type":"string","secret":false},{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":"Book a new appointment.\n\nRequired: patient_id, doctor_id, date (YYYY-MM-DD), time (HH:MM).\nOptional: reason, symptoms, is_follow_up, follow_up_of.\n\nThe slot must fall inside the doctor's working hours and be free.\nPatients can only book for their own patient profile.\n\nFollow-up linkage: pass follow_up_of=<original appointment id> to book a follow-up visit — see \"Book Follow-up Appointment\"."},{"id":"op_158","group":"Appointments","title":"Book Follow-up Appointment","method":"POST","path":"/appointments","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"patient_id","type":"string","secret":false},{"name":"doctor_id","type":"string","secret":false},{"name":"date","type":"string","secret":false},{"name":"time","type":"string","secret":false},{"name":"reason","type":"string","secret":false},{"name":"follow_up_of","type":"string","secret":false}]},"multipart":[],"description":"Book the follow-up recommended by a completed consultation.\n\nfollow_up_of: id of the ORIGINAL appointment (take it from a calendar follow_up_due event's appointment_id, or from the dashboard).\n\nServer-side validation:\n  - the original must exist in this hospital (404 otherwise)\n  - it must belong to the same patient (400 otherwise)\n  - is_follow_up is set automatically on a valid link\n\nOnce booked (any status except cancelled/no_show), the follow_up_due reminder disappears from calendar and dashboard. Cancelling the booked visit brings the reminder back."},{"id":"op_159","group":"Appointments","title":"Get Appointment","method":"GET","path":"/appointments/{{appointment_id}}","query":[],"parameters":["appointment_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_160","group":"Appointments","title":"Reschedule (update)","method":"PUT","path":"/appointments/{{appointment_id}}","query":[],"parameters":["appointment_id"],"body":{"type":"object","fields":[{"name":"date","type":"string","secret":false},{"name":"time","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_161","group":"Appointments","title":"Change Status","method":"PATCH","path":"/appointments/{{appointment_id}}/status","query":[],"parameters":["appointment_id"],"body":{"type":"object","fields":[{"name":"status","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_162","group":"Doctor Dashboard","title":"Dashboard Summary","method":"GET","path":"/dashboard/doctor","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Everything the doctor dashboard screen needs in ONE call.\n\nResponse data:\n  profile               — full doctor profile + user info\n  today                 — date, total, by_status (zero-filled), remaining, in_progress + next_appointment objects (with patient), current_token, next_token\n  week                  — rolling last 7 days: appointments, completed, unique_patients\n  month                 — calendar month-to-date: same fields\n  pending               — draft_prescriptions, lab_results_awaited, lab_results_ready_7d, follow_ups_due_7d (unbooked only)\n  totals                — all-time: appointments_completed, unique_patients, prescriptions, lab_orders\n  unread_notifications  — badge count\n\nAccess: doctor (own data) | hospital_admin & superadmin must pass ?doctor_id= | other roles 403."},{"id":"op_163","group":"Doctor Dashboard","title":"Today's Queue","method":"GET","path":"/dashboard/doctor/today","query":["date","status"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"The doctor's appointment queue for one day, ordered by time.\n\nResponse data: date, total, by_status (zero-filled), items[] — full appointment objects with patient briefs.\n\nAccess: doctor (own) | admin with ?doctor_id=."},{"id":"op_164","group":"Doctor Dashboard","title":"Schedule Strip (next N days)","method":"GET","path":"/dashboard/doctor/schedule","query":["days"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Per-day appointment counts for the next N days, zero-filled so the UI can render a continuous calendar strip.\n\nEach entry: date, day_of_week (0=Mon…6=Sun), is_working (from the doctor's available_days), total, active, by_status.\n\nAccess: doctor (own) | admin with ?doctor_id=."},{"id":"op_165","group":"Doctor Dashboard","title":"Recent Patients","method":"GET","path":"/dashboard/doctor/recent-patients","query":["limit"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Distinct patients from the doctor's COMPLETED appointments, most recent first.\n\nEach item: patient brief (number, name, age, gender, blood group, phone) + last_visit date + visit_count.\n\nAccess: doctor (own) | admin with ?doctor_id=."},{"id":"op_166","group":"Calendar","title":"Month View","method":"GET","path":"/calendar/month","query":["year","month"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Month-grid summary: one zero-filled entry per day of the month.\n\nResponse data: year, month, from, to, total, follow_ups_due, by_status (month totals), days[] — each with date, day_of_week (0=Mon…6=Sun), total, active, follow_ups_due, by_status.\n\nfollow_ups_due counts recommended follow-ups NOT booked yet, due that day.\n\nAdmin/staff-only filters: ?doctor_id= ?patient_id= ?department_id= (ignored for doctor/patient tokens, whose scope is fixed to their own records)."},{"id":"op_167","group":"Calendar","title":"Events (range)","method":"GET","path":"/calendar/events","query":["from","to"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Typed calendar events grouped per day (zero-filled continuous strip) — for week / agenda views.\n\nTwo event types:\n  type=appointment   — booked visit: id, appointment_number, title, date, start_time, end_time (computed from duration), status, reason, token_number, is_follow_up, follow_up_of, follow_up_date, patient + doctor briefs.\n  type=follow_up_due — recommended follow-up not booked yet (all-day item on its due date): id (\"followup:<id>\" — never collides), appointment_id (the original consultation), title, date, status=\"due\", is_overdue, original_date, diagnosis, reason, patient + doctor briefs.\n\ntitle is viewer-aware: staff see the patient name, patients see the doctor name.\n\nResponse data: from, to, total, appointments, follow_ups_due, days[] — each with date, day_of_week, total, events[] (reminders first, then appointments in time order).\n\nAdmin/staff-only filters: ?doctor_id= ?patient_id= ?department_id= (ignored for doctor/patient tokens, whose scope is fixed to their own records)."},{"id":"op_168","group":"Calendar","title":"Day View","method":"GET","path":"/calendar/day","query":["date"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Single-day timeline: events ordered by time + by_status counts.\n\nWhen the view is for ONE doctor (doctor token, or admin passing ?doctor_id=), working_hours is included: is_working_day, available_from/to, consultation_duration, is_available — so the UI can draw the time grid. Otherwise working_hours is null.\n\nEvents use the same typed format as Events (range).\n\nAdmin/staff-only filters: ?doctor_id= ?patient_id= ?department_id= (ignored for doctor/patient tokens, whose scope is fixed to their own records)."},{"id":"op_169","group":"Reports & Analytics","title":"Hospital Overview (KPIs)","method":"GET","path":"/reports/overview","query":["hospital_id"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"One-call KPI snapshot for the admin dashboard.\n\nResponse data: patients (total, new_this_month), appointments (today by status, this_month, this_month_completed), revenue (collected_today, collected_this_month, outstanding_balance), staff.active_doctors, lab.pending_orders, prescriptions.this_month, pharmacy (batches_expiring_30d, expired_batches_in_stock).\n\nAccess: hospital_admin, org_admin / org_viewer, superadmin - AND a current reports unlock (see the Reports Access folder). accountant, pharmacist and lab_technician NO LONGER have report access."},{"id":"op_170","group":"Reports & Analytics","title":"Revenue Report","method":"GET","path":"/reports/revenue","query":["from","to","hospital_id","group_by"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Financial analytics for a date range.\n\nResponse data:\n  totals — bills, billed, collected, outstanding, discount_given, tax_collected\n  billed_series / collected_series — per day|month buckets\n  by_payment_method — cash/card/upi/insurance/bank_transfer\n  by_item_type — consultation/lab_test/medicine/…\n\nBilled = bills with status other than draft/cancelled (by bill_date). Collected = payments (by payment_date).\n\nAccess: hospital_admin, org_admin / org_viewer, superadmin - AND a current reports unlock (see the Reports Access folder). accountant, pharmacist and lab_technician NO LONGER have report access."},{"id":"op_171","group":"Reports & Analytics","title":"Appointments Report","method":"GET","path":"/reports/appointments","query":["from","to","hospital_id","group_by"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Appointment analytics for a date range.\n\nResponse data: totals (by_status, follow_ups, completion / cancellation / no_show rates as %), volume series (total + completed per bucket), by_doctor top-20 (appointments, completed, unique_patients).\n\nAccess: hospital_admin, org_admin / org_viewer, superadmin - AND a current reports unlock (see the Reports Access folder). accountant, pharmacist and lab_technician NO LONGER have report access."},{"id":"op_172","group":"Reports & Analytics","title":"Patients Report (demographics)","method":"GET","path":"/reports/patients","query":["from","to","hospital_id","group_by"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Patient analytics: registrations series for the range + demographics across ALL active patients — by_gender, by_blood_group, by_disease_category, by_age_bucket (0-12/13-17/18-30/31-45/46-60/60+/unknown), top_cities.\n\nAccess: hospital_admin, org_admin / org_viewer, superadmin - AND a current reports unlock (see the Reports Access folder). accountant, pharmacist and lab_technician NO LONGER have report access."},{"id":"op_173","group":"Reports & Analytics","title":"Doctor Performance Report","method":"GET","path":"/reports/doctors","query":["from","to","hospital_id"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Per-doctor performance table for the range: appointments / completed / cancelled / no_shows, unique_patients, prescriptions, lab_orders, and revenue_collected (paid amounts on bills linked to the doctor's appointments).\n\nAccess: hospital_admin, org_admin / org_viewer, superadmin - AND a current reports unlock (see the Reports Access folder). accountant, pharmacist and lab_technician NO LONGER have report access."},{"id":"op_174","group":"Reports & Analytics","title":"Pharmacy Report","method":"GET","path":"/reports/pharmacy","query":["from","to","hospital_id"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Pharmacy analytics.\n\ninventory (current snapshot): batches_in_stock, units_in_stock, valuation_at_cost, valuation_at_mrp, batches_expiring_30d, expired_batches_in_stock.\nmovement (for the range): transactions + units per transaction type (in/out/adjustments/…).\ntop_dispensed: top-10 medicines by units dispensed in the range.\n\nAccess: hospital_admin, org_admin / org_viewer, superadmin - AND a current reports unlock (see the Reports Access folder). accountant, pharmacist and lab_technician NO LONGER have report access."},{"id":"op_175","group":"Reports & Analytics","title":"Prescribed Medicines","method":"GET","path":"/reports/prescribed-medicines","query":["group_by","from","to","medicine_id","hospital_id","limit"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"What was actually prescribed, and what it earned.\n\nCounts only ISSUED prescriptions (issued or dispensed) - a draft is a doctor still thinking, not a prescription.\n\nQUERY\n  ?group_by=    medicine (default) | hospital | doctor | patient\n  ?from= ?to=   YYYY-MM-DD, default last 30 days, max 366\n  ?medicine_id= narrow every grouping to a single drug\n  ?hospital_id= drill into one hospital of an organisation\n  ?limit=       rows returned, default 50, max 200\n\nEVERY GROUPING RETURNS prescription_count, line_items, total_quantity, dispensed_lines, patient_count and doctor_count. group_by=medicine adds the drug details and its revenue; hospital adds site revenue; doctor and patient add distinct_medicines.\n\nREVENUE comes from BILLED medicine lines (bill_items.medicine_id), not from the prescription - a prescription is an instruction, a bill is money. Only issued / partially-paid / paid bills count; a draft bill is not revenue.\n\nunattributed_revenue reports billed medicine lines with no medicine_id (rows created before that link existed, or keyed in by hand). They are surfaced rather than spread across drugs by guesswork, so totals still reconcile and the per-drug figures can be trusted for what they cover."},{"id":"op_176","group":"Reports & Analytics","title":"Lab Report","method":"GET","path":"/reports/labs","query":["from","to","hospital_id","group_by"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Lab analytics for the range: orders by_status, volume series, test-level totals (tests, tests_resulted, abnormal_results, abnormal_rate_pct), top-10 test names.\n\nAccess: hospital_admin, org_admin / org_viewer, superadmin - AND a current reports unlock (see the Reports Access folder). accountant, pharmacist and lab_technician NO LONGER have report access."},{"id":"op_177","group":"Reports Access (step-up password)","title":"Reports Auth Status","method":"GET","path":"/reports/auth/status","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Which screen should the UI show? Returns is_set, is_unlocked, is_locked_out, attempts_left, seconds left on the current unlock, and a next_step of forbidden | setup | unlock | locked_out | ready."},{"id":"op_178","group":"Reports Access (step-up password)","title":"Set Up Reports Password","method":"POST","path":"/reports/auth/setup","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"password","type":"string","secret":true},{"name":"confirm_password","type":"string","secret":true}]},"multipart":[],"description":"First-time setup. At least 10 characters with upper, lower, digit and symbol, and it must differ from your LOGIN password - a second factor identical to the first protects nothing.\n\nCan only be done once. Changing it afterwards needs the current password, so someone at an unattended session cannot silently take over reports access."},{"id":"op_179","group":"Reports Access (step-up password)","title":"Unlock Reports","method":"POST","path":"/reports/auth/unlock","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"password","type":"string","secret":true}]},"multipart":[],"description":"Opens a 15-minute sliding window on THIS access token.\n\n5 wrong attempts lock reports for 15 minutes; the error counts down the attempts remaining so the UI can warn before the last one.\n\nThe unlock does not travel: another device holding a different token is still locked."},{"id":"op_180","group":"Reports Access (step-up password)","title":"Lock Reports","method":"POST","path":"/reports/auth/lock","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Close the window immediately - the \"lock\" button."},{"id":"op_181","group":"Reports Access (step-up password)","title":"Change Reports Password","method":"POST","path":"/reports/auth/change-password","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"current_password","type":"string","secret":true},{"name":"new_password","type":"string","secret":true},{"name":"confirm_password","type":"string","secret":true}]},"multipart":[],"description":"Requires the current password. A successful change also LOCKS reports, so the new password must be used to get back in."},{"id":"op_182","group":"Reports Access (step-up password)","title":"Forgot Reports Password","method":"POST","path":"/reports/auth/forgot-password","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Sends a one-time code to YOUR registered email address. Self-service and tied to the account already signed in, so no administrator ever learns another person's reports password.\n\nThe response masks the address (j***e\nexample.com)."},{"id":"op_183","group":"Reports Access (step-up password)","title":"Reset Reports Password (with OTP)","method":"POST","path":"/reports/auth/reset-password","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"otp","type":"string","secret":true},{"name":"new_password","type":"string","secret":true},{"name":"confirm_password","type":"string","secret":true}]},"multipart":[],"description":"Finish the reset with the emailed code.\n\nThe new password is validated BEFORE the code is consumed, so a weak choice does not cost you the one-time code."},{"id":"op_184","group":"Reports Access (step-up password)","title":"Force-Reset Another User (admin)","method":"DELETE","path":"/reports/auth/credential/{{user_id}}","query":[],"parameters":["user_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"The escape hatch when someone has lost access to their email.\n\nSuperadmin, or an organisation admin for a user inside their own group.\n\nThe credential is DELETED, not replaced: the user sets a fresh one themselves, so no administrator ever holds someone else's reports password. Both sides of the action are written to the security log."},{"id":"op_185","group":"Prescriptions","title":"List Prescriptions","method":"GET","path":"/prescriptions","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_186","group":"Prescriptions","title":"Create Prescription","method":"POST","path":"/prescriptions","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"patient_id","type":"string","secret":false},{"name":"doctor_id","type":"string","secret":false},{"name":"diagnosis","type":"string","secret":false},{"name":"medications","type":"array","item":{"type":"object","fields":[{"name":"medicine_id","type":"string","secret":false},{"name":"dosage","type":"string","secret":false},{"name":"frequency","type":"string","secret":false},{"name":"duration","type":"string","secret":false},{"name":"quantity","type":"number","secret":false}]}},{"name":"lab_tests","type":"array","item":{"type":"object","fields":[{"name":"catalog_id","type":"string","secret":false},{"name":"priority","type":"string","secret":false},{"name":"instructions","type":"string","secret":false}]}}]},"multipart":[],"description":"Create a prescription. It starts as a DRAFT and stays private to the doctor until issued.\n\nmedications: as before - medicine_id from the master, or a free-text medicine_name for a one-off.\n\nlab_tests (NEW): laboratory tests the doctor is ordering.\n  catalog_id   - from Lab Tests -> Catalogue Dropdown (preferred: the lab then inherits sample type, unit and normal range without retyping)\n  test_name    - free text for a one-off test not in the catalogue\n  priority     - routine | urgent | stat (default routine)\n  instructions - clinical context, e.g. \"fasting sample\"\n  Each entry needs a catalog_id OR a test_name. The same test twice on one prescription is rejected.\n\nLab tests reach the Laboratory module only when the prescription is ISSUED - see Issue Prescription. A draft never puts work in the lab queue."},{"id":"op_187","group":"Prescriptions","title":"Create Prescription (lab tests only)","method":"POST","path":"/prescriptions","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"patient_id","type":"string","secret":false},{"name":"doctor_id","type":"string","secret":false},{"name":"diagnosis","type":"string","secret":false},{"name":"lab_tests","type":"array","item":{"type":"object","fields":[{"name":"catalog_id","type":"string","secret":false}]}}]},"multipart":[],"description":"A prescription may be lab-only. Issuing it no longer requires a medication."},{"id":"op_188","group":"Prescriptions","title":"Get Prescription","method":"GET","path":"/prescriptions/{{prescription_id}}","query":[],"parameters":["prescription_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_189","group":"Prescriptions","title":"Update Prescription","method":"PUT","path":"/prescriptions/{{prescription_id}}","query":[],"parameters":["prescription_id"],"body":{"type":"object","fields":[{"name":"diagnosis","type":"string","secret":false},{"name":"notes","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_190","group":"Prescriptions","title":"Issue Prescription (creates the lab order)","method":"PATCH","path":"/prescriptions/{{prescription_id}}/issue","query":[],"parameters":["prescription_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Issue a draft prescription.\n\nIf it carries lab tests, the LabOrder is created in the SAME transaction and its number comes back in the message. Either the prescription is issued AND the lab order exists, or neither happened.\n\nIdempotent: lab_orders.prescription_id is UNIQUE at the database level, so a retried request can never produce a second order.\n\nIssuing no longer requires a medication - a prescription with only lab tests is valid.\n\nResponses include lab_tests, lab_order_id and lab_order_number."},{"id":"op_191","group":"Prescriptions","title":"Dispense Prescription (deducts stock FEFO)","method":"PATCH","path":"/prescriptions/{{prescription_id}}/dispense","query":[],"parameters":["prescription_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_192","group":"Prescriptions","title":"Add Medication","method":"POST","path":"/prescriptions/{{prescription_id}}/medications","query":[],"parameters":["prescription_id"],"body":{"type":"object","fields":[{"name":"medicine_id","type":"string","secret":false},{"name":"dosage","type":"string","secret":false},{"name":"frequency","type":"string","secret":false},{"name":"quantity","type":"number","secret":false}]},"multipart":[],"description":""},{"id":"op_193","group":"Prescriptions","title":"Remove Medication","method":"DELETE","path":"/prescriptions/{{prescription_id}}/medications/{{medication_id}}","query":[],"parameters":["prescription_id","medication_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_194","group":"Prescriptions","title":"Add Lab Test to Prescription","method":"POST","path":"/prescriptions/{{prescription_id}}/lab-tests","query":[],"parameters":["prescription_id"],"body":{"type":"object","fields":[{"name":"catalog_id","type":"string","secret":false},{"name":"priority","type":"string","secret":false},{"name":"instructions","type":"string","secret":false}]},"multipart":[],"description":"Add one laboratory test to a DRAFT prescription.\n\ncatalog_id (preferred, from Lab Tests -> Catalogue Dropdown) or a free-text test_name. priority: routine | urgent | stat.\n\nDraft only, and doctors may only edit their own prescription. The test reaches the lab when the prescription is issued."},{"id":"op_195","group":"Prescriptions","title":"Remove Lab Test from Prescription","method":"DELETE","path":"/prescriptions/{{prescription_id}}/lab-tests/{{rx_lab_test_id}}","query":[],"parameters":["prescription_id","rx_lab_test_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Draft only."},{"id":"op_196","group":"Lab Tests","title":"List Lab Orders","method":"GET","path":"/lab-tests","query":["patient_id","status","hospital_id"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Lab orders for the caller. Each order now carries prescription_id and is_from_prescription, so the FE can badge doctor-ordered work.\n\nhospital_id narrows an organisation-wide caller to one hospital; it can never widen scope."},{"id":"op_197","group":"Lab Tests","title":"Pending Tests for a Patient","method":"GET","path":"/lab-tests/pending","query":["patient_id"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"THE LABORATORY QUEUE - what the lab loads when a patient is selected.\n\nEvery test still awaiting work for that patient, flattened across orders and sorted stat -> urgent -> routine, then oldest first.\n\nEach row carries catalog_id, test_name, test_category, sample_type, unit, normal_range and priority already populated, so a test the doctor prescribed needs NO retyping.\n\nProvenance: is_prescribed tells you whether a doctor ordered it on a prescription or the lab keyed it in, and doctor_name / prescription_id link back.\n\nReturns { patient, total_items, prescribed, items: [...] }."},{"id":"op_198","group":"Lab Tests","title":"Create Lab Order (manual)","method":"POST","path":"/lab-tests","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"patient_id","type":"string","secret":false},{"name":"doctor_id","type":"string","secret":false},{"name":"tests","type":"array","item":{"type":"object","fields":[{"name":"catalog_id","type":"string","secret":false},{"name":"priority","type":"string","secret":false}]}}]},"multipart":[],"description":"Keyed in by the lab or a doctor directly, as opposed to arriving via a prescription.\n\nEach test takes a catalog_id (preferred - category, sample type, unit and normal range are inherited) or a free-text test_name.\n\nOpen to doctor, hospital_admin and lab_technician.\n\nThe response includes duplicate_warnings listing any test already pending for this patient - the order is still created, the lab is just told rather than silently ending up with two."},{"id":"op_199","group":"Lab Tests","title":"Get Lab Order","method":"GET","path":"/lab-tests/{{lab_order_id}}","query":[],"parameters":["lab_order_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_200","group":"Lab Tests","title":"Update Order Status","method":"PATCH","path":"/lab-tests/{{lab_order_id}}/status","query":[],"parameters":["lab_order_id"],"body":{"type":"object","fields":[{"name":"status","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_201","group":"Lab Tests","title":"Update Test Result","method":"PUT","path":"/lab-tests/{{lab_order_id}}/tests/{{test_id}}","query":[],"parameters":["lab_order_id","test_id"],"body":{"type":"object","fields":[{"name":"result_value","type":"string","secret":false},{"name":"unit","type":"string","secret":false},{"name":"normal_range","type":"string","secret":false},{"name":"is_abnormal","type":"boolean","secret":false}]},"multipart":[],"description":"Enter or update one result. Only allowed once the sample has been collected.\n\nThe ORDER status is then kept in step with its test lines automatically: partial results move it to processing, and the last result completes it and drops it off the lab queue."},{"id":"op_202","group":"Lab Tests","title":"Lab Catalogue — List","method":"GET","path":"/lab-tests/catalog","query":["search","category","sample_type","include_inactive","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"The shared vocabulary between the doctor prescribing a test and the lab running it, so the two are the same RECORD rather than two strings that happen to match.\n\nScope follows the Medicine convention: hospital_id NULL = global entry (visible to every hospital), otherwise hospital-specific. A hospital sees global entries UNION its own.\n\nShips with 54 seeded global tests (CBC, LFT, KFT, HbA1c, lipid profile, thyroid profile, urine routine, dengue, HIV, X-ray, USG and more) - run python seed.py to install them.\n\nReference ranges are common adult defaults and vary by analyser and method: each lab should review them, or add a hospital-specific entry.\n\nprice is NULL on global entries - pricing is per-hospital."},{"id":"op_203","group":"Lab Tests","title":"Lab Catalogue — Dropdown (typeahead)","method":"GET","path":"/lab-tests/catalog/dropdown","query":["search","category","limit"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Typeahead source for the doctor \"prescribe a lab test\" picker and the lab order form.\n\nReturns value/label plus code, category, sample_type, unit, normal_range and price, so the FE can show units inline.\n\nSuggested UX: one combobox that searches this, with a final \"add as a custom test\" row when nothing matches - the catalogue becomes the path of least resistance while free text stays available."},{"id":"op_204","group":"Lab Tests","title":"Lab Catalogue — Add Test","method":"POST","path":"/lab-tests/catalog","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"code","type":"string","secret":false},{"name":"name","type":"string","secret":false},{"name":"category","type":"string","secret":false},{"name":"sample_type","type":"string","secret":false},{"name":"unit","type":"string","secret":false},{"name":"normal_range","type":"string","secret":false},{"name":"price","type":"number","secret":false},{"name":"turnaround_hours","type":"number","secret":false},{"name":"preparation","type":"string","secret":false}]},"multipart":[],"description":"Add a HOSPITAL-SPECIFIC test. hospital_admin or lab_technician.\n\nThe code must be unique across everything the hospital can see, so a local entry cannot shadow a global one (409 if it clashes).\n\ncategory and sample_type are validated - see Lookups -> Lab Test Categories / Lab Sample Types."},{"id":"op_205","group":"Lab Tests","title":"Lab Catalogue — Update Test","method":"PUT","path":"/lab-tests/catalog/{{lab_catalog_id}}","query":[],"parameters":["lab_catalog_id"],"body":{"type":"object","fields":[{"name":"price","type":"number","secret":false},{"name":"normal_range","type":"string","secret":false},{"name":"is_active","type":"boolean","secret":false}]},"multipart":[],"description":"Update one of the hospital's own entries. Global entries are read-only here (403) - create a hospital-specific entry to override one."},{"id":"op_206","group":"Billing","title":"List Bills","method":"GET","path":"/billing","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_207","group":"Billing","title":"Create Bill","method":"POST","path":"/billing","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"patient_id","type":"string","secret":false},{"name":"items","type":"array","item":{"type":"object","fields":[{"name":"description","type":"string","secret":false},{"name":"quantity","type":"number","secret":false},{"name":"unit_price","type":"number","secret":false},{"name":"item_type","type":"string","secret":false}]}}]},"multipart":[],"description":""},{"id":"op_208","group":"Billing","title":"Get Bill","method":"GET","path":"/billing/{{bill_id}}","query":[],"parameters":["bill_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_209","group":"Billing","title":"Issue Bill","method":"PATCH","path":"/billing/{{bill_id}}/issue","query":[],"parameters":["bill_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_210","group":"Billing","title":"Cancel Bill","method":"PATCH","path":"/billing/{{bill_id}}/cancel","query":[],"parameters":["bill_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_211","group":"Billing","title":"Add Bill Item","method":"POST","path":"/billing/{{bill_id}}/items","query":[],"parameters":["bill_id"],"body":{"type":"object","fields":[{"name":"description","type":"string","secret":false},{"name":"quantity","type":"number","secret":false},{"name":"unit_price","type":"number","secret":false},{"name":"item_type","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_212","group":"Billing","title":"Remove Bill Item","method":"DELETE","path":"/billing/{{bill_id}}/items/{{bill_item_id}}","query":[],"parameters":["bill_id","bill_item_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_213","group":"Billing","title":"List Payments","method":"GET","path":"/billing/{{bill_id}}/payments","query":[],"parameters":["bill_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_214","group":"Billing","title":"Add Payment","method":"POST","path":"/billing/{{bill_id}}/payments","query":[],"parameters":["bill_id"],"body":{"type":"object","fields":[{"name":"amount","type":"number","secret":false},{"name":"payment_method","type":"string","secret":false},{"name":"reference_number","type":"string","secret":false}]},"multipart":[],"description":"Record a payment against an issued bill.\n\nMandatory: amount, reference_number (transaction/receipt reference — UPI txn id, card auth code, cheque no, or an internal receipt number for cash).\npayment_method defaults to cash."},{"id":"op_215","group":"Billing","title":"Generate Bill from Appointment","method":"POST","path":"/billing/generate-from-appointment/{{appointment_id}}","query":[],"parameters":["appointment_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_216","group":"IPD · Wards & Beds","title":"Create Ward","method":"POST","path":"/ipd/wards","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"name","type":"string","secret":false},{"name":"code","type":"string","secret":false},{"name":"ward_type","type":"string","secret":false},{"name":"floor","type":"string","secret":false},{"name":"gender_restriction","type":"string","secret":false},{"name":"department_id","type":"string","secret":false}]},"multipart":[],"description":"ward_type: general | semi_private | private | deluxe | icu | hdu | nicu | picu | isolation | day_care (see Lookups → IPD).\ngender_restriction any|male|female is enforced when a bed is claimed, so a male patient cannot be placed in a female ward."},{"id":"op_217","group":"IPD · Wards & Beds","title":"List Wards","method":"GET","path":"/ipd/wards","query":["is_active"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_218","group":"IPD · Wards & Beds","title":"Update Ward","method":"PUT","path":"/ipd/wards/{{ward_id}}","query":[],"parameters":["ward_id"],"body":{"type":"object","fields":[{"name":"name","type":"string","secret":false},{"name":"floor","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_219","group":"IPD · Wards & Beds","title":"Create Bed Class","method":"POST","path":"/ipd/bed-classes","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"name","type":"string","secret":false},{"name":"code","type":"string","secret":false},{"name":"bed_charge","type":"number","secret":false},{"name":"nursing_charge","type":"number","secret":false},{"name":"visit_charge","type":"number","secret":false},{"name":"min_deposit","type":"number","secret":false},{"name":"is_day_care","type":"boolean","secret":false}]},"multipart":[],"description":"The tariff. bed_charge + nursing_charge is the daily rate that appears on the financial consent; visit_charge is billed per doctor visit; min_deposit is checked at admission."},{"id":"op_220","group":"IPD · Wards & Beds","title":"List Bed Classes","method":"GET","path":"/ipd/bed-classes","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_221","group":"IPD · Wards & Beds","title":"Update Bed Class","method":"PUT","path":"/ipd/bed-classes/{{bed_class_id}}","query":[],"parameters":["bed_class_id"],"body":{"type":"object","fields":[{"name":"bed_charge","type":"number","secret":false},{"name":"min_deposit","type":"number","secret":false}]},"multipart":[],"description":"Changing a tariff does not re-price stays in progress — each bed stay charges from the rate captured when it started."},{"id":"op_222","group":"IPD · Wards & Beds","title":"Create Beds (bulk)","method":"POST","path":"/ipd/beds","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"ward_id","type":"string","secret":false},{"name":"bed_class_id","type":"string","secret":false},{"name":"prefix","type":"string","secret":false},{"name":"start","type":"number","secret":false},{"name":"count","type":"number","secret":false}]},"multipart":[],"description":"Creates B-11 … B-14 in one call. For a single bed send {ward_id, bed_class_id, bed_number} instead."},{"id":"op_223","group":"IPD · Wards & Beds","title":"List Beds","method":"GET","path":"/ipd/beds","query":["ward_id","status"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_224","group":"IPD · Wards & Beds","title":"Update Bed","method":"PUT","path":"/ipd/beds/{{bed_id}}","query":[],"parameters":["bed_id"],"body":{"type":"object","fields":[{"name":"ward_id","type":"string","secret":false},{"name":"bed_class_id","type":"string","secret":false},{"name":"is_active","type":"boolean","secret":false}]},"multipart":[],"description":""},{"id":"op_225","group":"IPD · Wards & Beds","title":"Block Bed","method":"PATCH","path":"/ipd/beds/{{bed_id}}/block","query":[],"parameters":["bed_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":"Takes a bed out of service. An occupied bed cannot be blocked."},{"id":"op_226","group":"IPD · Wards & Beds","title":"Unblock Bed","method":"PATCH","path":"/ipd/beds/{{bed_id}}/unblock","query":[],"parameters":["bed_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_227","group":"IPD · Wards & Beds","title":"Mark Bed Clean","method":"PATCH","path":"/ipd/beds/{{bed_id}}/mark-clean","query":[],"parameters":["bed_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"After a discharge a bed goes to \"cleaning\"; housekeeping marks it clean to return it to the pool."},{"id":"op_228","group":"IPD · Wards & Beds","title":"Bed Board","method":"GET","path":"/ipd/bed-board","query":["ward_id"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Live occupancy grid for the ward screen. Also expires stale bed holds as a side effect."},{"id":"op_229","group":"IPD · Admission Requests","title":"Create Admission Request","method":"POST","path":"/admission-requests","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"patient_id","type":"string","secret":false},{"name":"bed_class_id","type":"string","secret":false},{"name":"attending_doctor_id","type":"string","secret":false},{"name":"department_id","type":"string","secret":false},{"name":"admission_type","type":"string","secret":false},{"name":"priority","type":"string","secret":false},{"name":"source","type":"string","secret":false},{"name":"planned_date","type":"string","secret":false},{"name":"expected_stay_days","type":"number","secret":false},{"name":"reason","type":"string","secret":false},{"name":"provisional_diagnosis","type":"string","secret":false},{"name":"prescription_id","type":"string","secret":false},{"name":"appointment_id","type":"string","secret":false}]},"multipart":[],"description":"A doctor asking the desk for a bed.\n\nTo admit at another hospital in the same organisation add target_hospital_id and share_consent_by (who agreed to share the records) — that also issues a record-sharing consent here.\nFor a mid-stay transfer out, add source_admission_id."},{"id":"op_230","group":"IPD · Admission Requests","title":"List Admission Requests","method":"GET","path":"/admission-requests","query":["box","status","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"box=incoming (someone asking us) | outgoing (we asked) | all."},{"id":"op_231","group":"IPD · Admission Requests","title":"Get Admission Request","method":"GET","path":"/admission-requests/{{admission_request_id}}","query":[],"parameters":["admission_request_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_232","group":"IPD · Admission Requests","title":"Patient Matches (cross-hospital)","method":"GET","path":"/admission-requests/{{admission_request_id}}/patient-matches","query":[],"parameters":["admission_request_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Before admitting a patient sent from another hospital, shows the likely existing records here so you do not create a duplicate."},{"id":"op_233","group":"IPD · Admission Requests","title":"Accept — hold a bed","method":"PATCH","path":"/admission-requests/{{admission_request_id}}/accept","query":[],"parameters":["admission_request_id"],"body":{"type":"object","fields":[{"name":"bed_id","type":"string","secret":false},{"name":"target_patient_id","type":"string","secret":false}]},"multipart":[],"description":"Reserves the bed for bed_reservation_hold_hours (default 4). If the bed class assigned differs from the one requested, the patient must sign a tariff-change consent at admission."},{"id":"op_234","group":"IPD · Admission Requests","title":"Waitlist","method":"PATCH","path":"/admission-requests/{{admission_request_id}}/waitlist","query":[],"parameters":["admission_request_id"],"body":{"type":"object","fields":[{"name":"note","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_235","group":"IPD · Admission Requests","title":"Reject","method":"PATCH","path":"/admission-requests/{{admission_request_id}}/reject","query":[],"parameters":["admission_request_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_236","group":"IPD · Admission Requests","title":"Release held bed","method":"PATCH","path":"/admission-requests/{{admission_request_id}}/release","query":[],"parameters":["admission_request_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Frees the bed but keeps the request open."},{"id":"op_237","group":"IPD · Admission Requests","title":"Cancel","method":"PATCH","path":"/admission-requests/{{admission_request_id}}/cancel","query":[],"parameters":["admission_request_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_238","group":"IPD · Admissions","title":"Admit Patient","method":"POST","path":"/admissions","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"request_id","type":"string","secret":false},{"name":"attendant_name","type":"string","secret":false},{"name":"attendant_phone","type":"string","secret":false},{"name":"attendant_relation","type":"string","secret":false},{"name":"attending_doctor_id","type":"string","secret":false},{"name":"payer_type","type":"string","secret":false},{"name":"expected_discharge_date","type":"string","secret":false},{"name":"is_mlc","type":"boolean","secret":false},{"name":"mlc_number","type":"string","secret":false},{"name":"consents","type":"array","item":{"type":"object","fields":[{"name":"consent_type","type":"string","secret":false},{"name":"signed_by_name","type":"string","secret":false},{"name":"signed_by_relation","type":"string","secret":false}]}},{"name":"deposit","type":"object","fields":[{"name":"amount","type":"number","secret":false},{"name":"method","type":"string","secret":false},{"name":"reference","type":"string","secret":false}]}]},"multipart":[],"description":"Turns an accepted request into an admission and claims the bed.\n\nThe consents listed here are ISSUED, not signed — each becomes a pending consent with a serial and a deadline, and the signed scan is uploaded later (see the Consents folder).\ngeneral + financial are required unless the admission is an emergency, where they become a warning instead.\nReturns readmission_of_id when the patient was admitted here within the hospital readmission window."},{"id":"op_239","group":"IPD · Admissions","title":"List Admissions","method":"GET","path":"/admissions","query":["status","ward_id","readmission","search","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_240","group":"IPD · Admissions","title":"Get Admission","method":"GET","path":"/admissions/{{admission_id}}","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Full detail: bed, stays, consents, attendant, clinical snapshot."},{"id":"op_241","group":"IPD · Admissions","title":"Timeline","method":"GET","path":"/admissions/{{admission_id}}/timeline","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Everything that happened during the stay, in order."},{"id":"op_242","group":"IPD · Admissions","title":"Transfer Bed","method":"POST","path":"/admissions/{{admission_id}}/transfer-bed","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"bed_id","type":"string","secret":false},{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":"Closes the current bed stay and opens a new one. If the new bed class differs, bed-days are charged at each rate for the days spent in it — the tariff is never applied retrospectively."},{"id":"op_243","group":"IPD · Admissions","title":"Change Attending Doctor","method":"PATCH","path":"/admissions/{{admission_id}}/doctor","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"doctor_id","type":"string","secret":false},{"name":"department_id","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_244","group":"IPD · Admissions","title":"Set / Clear MLC","method":"PATCH","path":"/admissions/{{admission_id}}/mlc","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"is_mlc","type":"boolean","secret":false},{"name":"mlc_number","type":"string","secret":false}]},"multipart":[],"description":"Medico-legal case. An MLC admission cannot be discharged without the MLC number recorded, and a death additionally needs the police intimation reference."},{"id":"op_245","group":"IPD · Admissions","title":"Cancel Admission","method":"PATCH","path":"/admissions/{{admission_id}}/cancel","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":"Only within cancel_admission_window_hours. Cancelled admissions are excluded from every report."},{"id":"op_246","group":"IPD · Admissions","title":"Record a Consent (legacy shortcut)","method":"POST","path":"/admissions/{{admission_id}}/consents","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"consent_type","type":"string","secret":false},{"name":"signed_by_name","type":"string","secret":false},{"name":"signed_by_relation","type":"string","secret":false},{"name":"witness_name","type":"string","secret":false},{"name":"details","type":"string","secret":false}]},"multipart":[],"description":"Issues a pending consent against this admission. Prefer POST /consents, which takes the same fields plus language."},{"id":"op_247","group":"IPD · Clinical Notes","title":"Get Admission Note","method":"GET","path":"/admissions/{{admission_id}}/admission-note","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_248","group":"IPD · Clinical Notes","title":"Save Admission Note","method":"PUT","path":"/admissions/{{admission_id}}/admission-note","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"chief_complaint","type":"string","secret":false},{"name":"history_of_presenting_illness","type":"string","secret":false},{"name":"past_surgical_history","type":"string","secret":false},{"name":"allergies","type":"string","secret":false},{"name":"clinical_examination","type":"string","secret":false},{"name":"diagnosis","type":"string","secret":false},{"name":"investigation_notes","type":"string","secret":false},{"name":"advice","type":"string","secret":false},{"name":"plan","type":"string","secret":false}]},"multipart":[],"description":"Draft until signed. History fields are frozen from the patient profile at admission so the note shows what was known then."},{"id":"op_249","group":"IPD · Clinical Notes","title":"Sign Admission Note","method":"POST","path":"/admissions/{{admission_id}}/admission-note/sign","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"A signed note can no longer be edited — correct it with an amending progress note."},{"id":"op_250","group":"IPD · Clinical Notes","title":"Add Progress Note","method":"POST","path":"/admissions/{{admission_id}}/progress-notes","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"note_type","type":"string","secret":false},{"name":"subjective","type":"string","secret":false},{"name":"objective","type":"string","secret":false},{"name":"assessment","type":"string","secret":false},{"name":"plan","type":"string","secret":false},{"name":"sign","type":"boolean","secret":false},{"name":"amends_note_id","type":"string","secret":false}]},"multipart":[],"description":"SOAP note. note_type: doctor | nurse | handover | consultant. Nurses may write nurse and handover notes only.\nTo correct a signed note, post a new one with amends_note_id — the original is never edited."},{"id":"op_251","group":"IPD · Clinical Notes","title":"List Progress Notes","method":"GET","path":"/admissions/{{admission_id}}/progress-notes","query":["note_type","page","per_page"],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_252","group":"IPD · Clinical Notes","title":"Edit Progress Note (draft only)","method":"PUT","path":"/admissions/{{admission_id}}/progress-notes/{{progress_note_id}}","query":[],"parameters":["admission_id","progress_note_id"],"body":{"type":"object","fields":[{"name":"subjective","type":"string","secret":false},{"name":"plan","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_253","group":"IPD · Clinical Notes","title":"Sign Progress Note","method":"POST","path":"/admissions/{{admission_id}}/progress-notes/{{progress_note_id}}/sign","query":[],"parameters":["admission_id","progress_note_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_254","group":"IPD · Clinical Notes","title":"Get Discharge Summary","method":"GET","path":"/admissions/{{admission_id}}/discharge/summary","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_255","group":"IPD · Clinical Notes","title":"Save Discharge Summary","method":"PUT","path":"/admissions/{{admission_id}}/discharge/summary","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"diagnosis","type":"string","secret":false},{"name":"course_in_hospital","type":"string","secret":false},{"name":"procedures_done","type":"string","secret":false},{"name":"condition_at_discharge","type":"string","secret":false},{"name":"discharge_medications","type":"string","secret":false},{"name":"advice","type":"string","secret":false},{"name":"follow_up_advice","type":"string","secret":false},{"name":"follow_up_date","type":"string","secret":false},{"name":"death_at","type":"string","secret":false},{"name":"cause_of_death","type":"string","secret":false}]},"multipart":[],"description":"Created as a draft when discharge is initiated, pre-filled from the admission note. For a death discharge, death_at and cause_of_death are required before the discharge can complete."},{"id":"op_256","group":"IPD · Clinical Notes","title":"Sign Discharge Summary","method":"POST","path":"/admissions/{{admission_id}}/discharge/summary/sign","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_257","group":"IPD · Nursing & Medication","title":"Create Medication Order","method":"POST","path":"/admissions/{{admission_id}}/medication-orders","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"drug_name","type":"string","secret":false},{"name":"medicine_id","type":"string","secret":false},{"name":"dose","type":"string","secret":false},{"name":"route","type":"string","secret":false},{"name":"frequency","type":"string","secret":false},{"name":"schedule_times","type":"array","item":{"type":"string","secret":false}},{"name":"start_at","type":"string","secret":false},{"name":"duration_days","type":"number","secret":false},{"name":"end_at","type":"string","secret":false},{"name":"instructions","type":"string","secret":false},{"name":"prn_indication","type":"string","secret":false},{"name":"allergy_override_reason","type":"string","secret":false}]},"multipart":[],"description":"frequency od|bd|tds|qid|q6h|q8h|stat|prn — each carries default times (Lookups → IPD). A drug the patient is recorded allergic to is refused unless allergy_override_reason is given."},{"id":"op_258","group":"IPD · Nursing & Medication","title":"List Medication Orders","method":"GET","path":"/admissions/{{admission_id}}/medication-orders","query":["status"],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_259","group":"IPD · Nursing & Medication","title":"Hold / Resume / Stop Order","method":"PATCH","path":"/admissions/{{admission_id}}/medication-orders/{{medication_order_id}}/status","query":[],"parameters":["admission_id","medication_order_id"],"body":{"type":"object","fields":[{"name":"action","type":"string","secret":false},{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":"action: hold | resume | stop. Doses scheduled while an order was held are not counted as missed."},{"id":"op_260","group":"IPD · Nursing & Medication","title":"Acknowledge Order (nurse)","method":"POST","path":"/admissions/{{admission_id}}/medication-orders/{{medication_order_id}}/acknowledge","query":[],"parameters":["admission_id","medication_order_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_261","group":"IPD · Nursing & Medication","title":"Stop All Orders","method":"POST","path":"/admissions/{{admission_id}}/medication-orders/stop-all","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":"Discharge is blocked while any order is still active."},{"id":"op_262","group":"IPD · Nursing & Medication","title":"Chart a Dose","method":"POST","path":"/admissions/{{admission_id}}/medication-orders/{{medication_order_id}}/doses","query":[],"parameters":["admission_id","medication_order_id"],"body":{"type":"object","fields":[{"name":"scheduled_at","type":"string","secret":false},{"name":"given_at","type":"string","secret":false},{"name":"dose_given","type":"string","secret":false},{"name":"notes","type":"string","secret":false},{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":"One record per (order, scheduled slot) — charting the same slot twice is refused, and two nurses doing it at the same instant get a 409 rather than a duplicate.\nTo record a missed dose send reason instead of given_at."},{"id":"op_263","group":"IPD · Nursing & Medication","title":"Medication Administration Record","method":"GET","path":"/admissions/{{admission_id}}/mar","query":["date"],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"The MAR grid for one day: every scheduled slot with its status. Slots are calculated from the order, not stored."},{"id":"op_264","group":"IPD · Nursing & Medication","title":"Record Vitals","method":"POST","path":"/admissions/{{admission_id}}/vitals","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"recorded_at","type":"string","secret":false},{"name":"temperature_c","type":"number","secret":false},{"name":"pulse","type":"number","secret":false},{"name":"systolic_bp","type":"number","secret":false},{"name":"diastolic_bp","type":"number","secret":false},{"name":"resp_rate","type":"number","secret":false},{"name":"spo2","type":"number","secret":false},{"name":"on_oxygen","type":"boolean","secret":false},{"name":"oxygen_flow","type":"string","secret":false},{"name":"consciousness","type":"string","secret":false},{"name":"pain_score","type":"number","secret":false},{"name":"blood_sugar","type":"string","secret":false},{"name":"weight_kg","type":"number","secret":false},{"name":"notes","type":"string","secret":false}]},"multipart":[],"description":"NEWS2 score and risk band are calculated and returned. A high score notifies the attending doctor. temperature_f is accepted instead of temperature_c."},{"id":"op_265","group":"IPD · Nursing & Medication","title":"List Vitals","method":"GET","path":"/admissions/{{admission_id}}/vitals","query":["date","page","per_page"],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_266","group":"IPD · Nursing & Medication","title":"Set Vitals Frequency","method":"PATCH","path":"/admissions/{{admission_id}}/vitals-frequency","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"hours","type":"number","secret":false}]},"multipart":[],"description":"Drives the \"vitals due\" list on the nursing station."},{"id":"op_267","group":"IPD · Nursing & Medication","title":"Record Intake / Output","method":"POST","path":"/admissions/{{admission_id}}/fluids","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"direction","type":"string","secret":false},{"name":"route","type":"string","secret":false},{"name":"volume_ml","type":"number","secret":false},{"name":"recorded_at","type":"string","secret":false},{"name":"notes","type":"string","secret":false}]},"multipart":[],"description":"direction intake|output; route oral|iv|ngt|urine|drain|vomit|stool."},{"id":"op_268","group":"IPD · Nursing & Medication","title":"List Fluids","method":"GET","path":"/admissions/{{admission_id}}/fluids","query":["date"],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_269","group":"IPD · Nursing & Medication","title":"Fluid Balance","method":"GET","path":"/admissions/{{admission_id}}/fluid-balance","query":["date"],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Totals in, out and the running balance for one local day."},{"id":"op_270","group":"IPD · Nursing & Medication","title":"Order Labs from the Ward","method":"POST","path":"/admissions/{{admission_id}}/lab-orders","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"tests","type":"array","item":{"type":"object","fields":[{"name":"catalog_id","type":"string","secret":false},{"name":"notes","type":"string","secret":false}]}},{"name":"notes","type":"string","secret":false}]},"multipart":[],"description":"Creates a normal lab order linked to the admission, so the charge lands on the IPD bill."},{"id":"op_271","group":"IPD · Nursing & Medication","title":"List Lab Orders","method":"GET","path":"/admissions/{{admission_id}}/lab-orders","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_272","group":"IPD · Nursing & Medication","title":"Nursing Station","method":"GET","path":"/ipd/nursing-station","query":["ward_id"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"The ward worklist: who is due vitals, which doses are overdue, which patients are deteriorating by NEWS2."},{"id":"op_273","group":"IPD · Ward Pharmacy","title":"Raise Ward Indent","method":"POST","path":"/admissions/{{admission_id}}/indents","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"is_urgent","type":"boolean","secret":false},{"name":"notes","type":"string","secret":false},{"name":"items","type":"array","item":{"type":"object","fields":[{"name":"medicine_id","type":"string","secret":false},{"name":"quantity","type":"number","secret":false},{"name":"medication_order_id","type":"string","secret":false}]}}]},"multipart":[],"description":"The ward asking pharmacy for stock against this admission."},{"id":"op_274","group":"IPD · Ward Pharmacy","title":"List Indents for Admission","method":"GET","path":"/admissions/{{admission_id}}/indents","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_275","group":"IPD · Ward Pharmacy","title":"Pharmacy Queue","method":"GET","path":"/ipd/indents","query":["status","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_276","group":"IPD · Ward Pharmacy","title":"Dispense Indent","method":"POST","path":"/ipd/indents/{{indent_id}}/dispense","query":[],"parameters":["indent_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Issues from stock earliest-expiry-first, charges each batch at its own selling price, and warns about anything short or unpriced. Stock is never over-issued even under concurrent dispensing."},{"id":"op_277","group":"IPD · Ward Pharmacy","title":"Return Unused Medicines","method":"POST","path":"/ipd/indents/{{indent_id}}/return","query":[],"parameters":["indent_id"],"body":{"type":"object","fields":[{"name":"returns","type":"array","item":{"type":"object","fields":[{"name":"item_id","type":"string","secret":false},{"name":"quantity","type":"number","secret":false}]}}]},"multipart":[],"description":"Returns to stock and takes the value off the bill: the original charge is voided and a fresh one raised for what was kept."},{"id":"op_278","group":"IPD · Ward Pharmacy","title":"Cancel Indent","method":"POST","path":"/ipd/indents/{{indent_id}}/cancel","query":[],"parameters":["indent_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_279","group":"IPD · Charges, Deposits & Bill","title":"Add Charge","method":"POST","path":"/admissions/{{admission_id}}/charges","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"charge_type","type":"string","secret":false},{"name":"description","type":"string","secret":false},{"name":"quantity","type":"number","secret":false},{"name":"unit_price","type":"number","secret":false}]},"multipart":[],"description":"charge_type: procedure | service | consumable | pharmacy | lab | investigation | other. Pharmacy and lab charges are normally raised automatically by dispensing and by lab orders."},{"id":"op_280","group":"IPD · Charges, Deposits & Bill","title":"Void Charge","method":"PATCH","path":"/admissions/{{admission_id}}/charges/{{ipd_charge_id}}/void","query":[],"parameters":["admission_id","ipd_charge_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":"Charges are voided, never deleted — the original stays on the bill marked void."},{"id":"op_281","group":"IPD · Charges, Deposits & Bill","title":"Record Deposit","method":"POST","path":"/admissions/{{admission_id}}/deposits","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"amount","type":"number","secret":false},{"name":"method","type":"string","secret":false},{"name":"reference","type":"string","secret":false},{"name":"notes","type":"string","secret":false}]},"multipart":[],"description":"All money taken during a stay is a receipt against the admission, not a payment on the bill — that is what lets the final bill be rebuilt at discharge without losing anything."},{"id":"op_282","group":"IPD · Charges, Deposits & Bill","title":"Record Refund","method":"POST","path":"/admissions/{{admission_id}}/refunds","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"amount","type":"number","secret":false},{"name":"method","type":"string","secret":false},{"name":"reference","type":"string","secret":false},{"name":"notes","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_283","group":"IPD · Charges, Deposits & Bill","title":"Running Bill","method":"GET","path":"/admissions/{{admission_id}}/bill","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Live summary: bed-days, every charge, package cover, insurer and patient share, receipts and balance. Bed-days are calculated from the bed stays by the hospital bed-day rule, not stored."},{"id":"op_284","group":"IPD · Discharge","title":"Initiate Discharge","method":"POST","path":"/admissions/{{admission_id}}/discharge/initiate","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"discharge_type","type":"string","secret":false}]},"multipart":[],"description":"discharge_type: normal | lama | dama | referred | transferred | absconded | death. Creates the discharge summary draft."},{"id":"op_285","group":"IPD · Discharge","title":"Revoke Discharge","method":"POST","path":"/admissions/{{admission_id}}/discharge/revoke","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Puts the patient back to admitted and cancels the draft final bill."},{"id":"op_286","group":"IPD · Discharge","title":"Nursing Clearance","method":"POST","path":"/admissions/{{admission_id}}/discharge/nursing-clearance","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Lines out, belongings returned, discharge teaching done."},{"id":"op_287","group":"IPD · Discharge","title":"Pharmacy Clearance","method":"POST","path":"/admissions/{{admission_id}}/discharge/pharmacy-clearance","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Pharmacist confirms unused medicines are returned. Blocked while any indent is still waiting."},{"id":"op_288","group":"IPD · Discharge","title":"Generate Final Bill","method":"POST","path":"/admissions/{{admission_id}}/discharge/final-bill","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Builds the bill from the charges and bed-days as they stand. Can be regenerated while the patient is still admitted."},{"id":"op_289","group":"IPD · Discharge","title":"Discharge Clearances","method":"GET","path":"/admissions/{{admission_id}}/discharge/clearances","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"The checklist standing between this patient and the door: summary signed, nursing, orders stopped, pharmacy, signed consents on file, bill settled, plus LAMA / death / MLC items where they apply. Every item must be ok before complete will run."},{"id":"op_290","group":"IPD · Discharge","title":"Record Body Handover (death)","method":"POST","path":"/admissions/{{admission_id}}/discharge/body-handover","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"released_to","type":"string","secret":false},{"name":"relation","type":"string","secret":false},{"name":"released_at","type":"string","secret":false},{"name":"police_intimation_ref","type":"string","secret":false}]},"multipart":[],"description":"Only on a death discharge. The police reference is required when the case is medico-legal."},{"id":"op_291","group":"IPD · Discharge","title":"Complete Discharge","method":"POST","path":"/admissions/{{admission_id}}/discharge/complete","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Closes the stay, frees the bed for cleaning and applies the receipts to the bill. Fails listing whatever clearance is still outstanding."},{"id":"op_292","group":"IPD · Insurance & Packages","title":"Open Pre-authorisation","method":"POST","path":"/admissions/{{admission_id}}/preauth","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"insurer_name","type":"string","secret":false},{"name":"insurer_code","type":"string","secret":false},{"name":"tpa_code","type":"string","secret":false},{"name":"policy_number","type":"string","secret":false},{"name":"member_id","type":"string","secret":false},{"name":"requested_amount","type":"number","secret":false},{"name":"remarks","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_293","group":"IPD · Insurance & Packages","title":"Get Pre-authorisation","method":"GET","path":"/admissions/{{admission_id}}/preauth","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_294","group":"IPD · Insurance & Packages","title":"Add Pre-auth Event","method":"POST","path":"/admissions/{{admission_id}}/preauth/events","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"event","type":"string","secret":false},{"name":"amount","type":"number","secret":false},{"name":"reference_number","type":"string","secret":false},{"name":"note","type":"string","secret":false}]},"multipart":[],"description":"event: submitted | queried | approved | partially_approved | rejected | enhanced | cancelled. The whole conversation with the insurer is kept as an ordered event trail."},{"id":"op_295","group":"IPD · Insurance & Packages","title":"Apply Package","method":"POST","path":"/admissions/{{admission_id}}/package","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"package_id","type":"string","secret":false}]},"multipart":[],"description":"Fixes the price for what the package covers. Applying a package replaces any package already on the admission."},{"id":"op_296","group":"IPD · Insurance & Packages","title":"Get Applied Package","method":"GET","path":"/admissions/{{admission_id}}/package","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_297","group":"IPD · Insurance & Packages","title":"Remove Package","method":"DELETE","path":"/admissions/{{admission_id}}/package","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_298","group":"IPD · Insurance & Packages","title":"Mark Charge Outside Package","method":"PATCH","path":"/admissions/{{admission_id}}/charges/{{ipd_charge_id}}/package","query":[],"parameters":["admission_id","ipd_charge_id"],"body":{"type":"object","fields":[{"name":"outside_package","type":"boolean","secret":false}]},"multipart":[],"description":"Bills this charge separately even though its type is covered — for the complication the package price never anticipated."},{"id":"op_299","group":"IPD · Insurance & Packages","title":"Create Package","method":"POST","path":"/ipd/packages","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"name","type":"string","secret":false},{"name":"code","type":"string","secret":false},{"name":"price","type":"number","secret":false},{"name":"included_bed_days","type":"number","secret":false},{"name":"covers","type":"array","item":{"type":"string","secret":false}},{"name":"description","type":"string","secret":false},{"name":"is_active","type":"boolean","secret":false}]},"multipart":[],"description":""},{"id":"op_300","group":"IPD · Insurance & Packages","title":"List Packages","method":"GET","path":"/ipd/packages","query":["is_active"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_301","group":"IPD · Insurance & Packages","title":"Update Package","method":"PUT","path":"/ipd/packages/{{package_id}}","query":[],"parameters":["package_id"],"body":{"type":"object","fields":[{"name":"price","type":"number","secret":false},{"name":"is_active","type":"boolean","secret":false}]},"multipart":[],"description":""},{"id":"op_302","group":"IPD · Insurance & Packages","title":"List Claims","method":"GET","path":"/ipd/claims","query":["status","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"status=open shows everything not yet settled or rejected."},{"id":"op_303","group":"IPD · Insurance & Packages","title":"Get Claim","method":"GET","path":"/ipd/claims/{{claim_id}}","query":[],"parameters":["claim_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_304","group":"IPD · Insurance & Packages","title":"Act on Claim","method":"POST","path":"/ipd/claims/{{claim_id}}/action","query":[],"parameters":["claim_id"],"body":{"type":"object","fields":[{"name":"action","type":"string","secret":false},{"name":"settled_amount","type":"number","secret":false},{"name":"shortfall_action","type":"string","secret":false},{"name":"utr_number","type":"string","secret":false},{"name":"insurer_claim_ref","type":"string","secret":false},{"name":"note","type":"string","secret":false}]},"multipart":[],"description":"action: submit | query | settle | reject. On settle, shortfall_action decides who absorbs the difference — write_off (hospital) or collect_from_patient."},{"id":"op_305","group":"IPD · Care Plans","title":"Create Care Plan","method":"POST","path":"/care-plans","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"patient_id","type":"string","secret":false},{"name":"doctor_id","type":"string","secret":false},{"name":"name","type":"string","secret":false},{"name":"protocol","type":"string","secret":false},{"name":"total_cycles","type":"number","secret":false},{"name":"interval_days","type":"number","secret":false},{"name":"first_date","type":"string","secret":false},{"name":"bed_class_id","type":"string","secret":false},{"name":"package_id","type":"string","secret":false}]},"multipart":[],"description":"A course of day-care admissions planned in advance — chemotherapy, dialysis, transfusions. Every cycle is created up front with its planned date."},{"id":"op_306","group":"IPD · Care Plans","title":"List Care Plans","method":"GET","path":"/care-plans","query":["patient_id","status","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_307","group":"IPD · Care Plans","title":"Get Care Plan","method":"GET","path":"/care-plans/{{care_plan_id}}","query":[],"parameters":["care_plan_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"The plan with every cycle and its state: planned, booked, admitted, done, skipped."},{"id":"op_308","group":"IPD · Care Plans","title":"Book a Cycle","method":"POST","path":"/care-plans/{{care_plan_id}}/cycles/1/book","query":[],"parameters":["care_plan_id"],"body":{"type":"object","fields":[{"name":"provisional_diagnosis","type":"string","secret":false},{"name":"out_of_order","type":"boolean","secret":false}]},"multipart":[],"description":"Raises the admission request for that cycle. Booking out of order needs out_of_order=true, so a skipped cycle is a deliberate act."},{"id":"op_309","group":"IPD · Care Plans","title":"Postpone a Cycle","method":"PATCH","path":"/care-plans/{{care_plan_id}}/cycles/2/postpone","query":[],"parameters":["care_plan_id"],"body":{"type":"object","fields":[{"name":"new_date","type":"string","secret":false},{"name":"shift_following","type":"boolean","secret":false},{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":"shift_following moves every later cycle by the same interval, which is what actually happens when a course slips."},{"id":"op_310","group":"IPD · Care Plans","title":"Skip a Cycle","method":"PATCH","path":"/care-plans/{{care_plan_id}}/cycles/3/skip","query":[],"parameters":["care_plan_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_311","group":"IPD · Care Plans","title":"Cancel Care Plan","method":"PATCH","path":"/care-plans/{{care_plan_id}}/cancel","query":[],"parameters":["care_plan_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_312","group":"Referrals","title":"Create Referral","method":"POST","path":"/referrals","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"patient_id","type":"string","secret":false},{"name":"kind","type":"string","secret":false},{"name":"to_doctor_id","type":"string","secret":false},{"name":"to_department_id","type":"string","secret":false},{"name":"to_hospital_id","type":"string","secret":false},{"name":"external_facility","type":"string","secret":false},{"name":"external_doctor","type":"string","secret":false},{"name":"external_contact","type":"string","secret":false},{"name":"reason","type":"string","secret":false},{"name":"urgency","type":"string","secret":false},{"name":"prescription_id","type":"string","secret":false},{"name":"admission_id","type":"string","secret":false}]},"multipart":[],"description":"kind: internal_doctor | internal_department | group_hospital | external.\ngroup_hospital also needs share_consent_by — records only move between hospitals with the patient's recorded permission."},{"id":"op_313","group":"Referrals","title":"List Referrals","method":"GET","path":"/referrals","query":["box","status","patient_id","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_314","group":"Referrals","title":"Get Referral","method":"GET","path":"/referrals/{{referral_id}}","query":[],"parameters":["referral_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_315","group":"Referrals","title":"Respond (accept / decline)","method":"PATCH","path":"/referrals/{{referral_id}}/respond","query":[],"parameters":["referral_id"],"body":{"type":"object","fields":[{"name":"action","type":"string","secret":false},{"name":"note","type":"string","secret":false}]},"multipart":[],"description":"Only the receiving side may respond, and declining needs a reason."},{"id":"op_316","group":"Referrals","title":"Complete Referral","method":"PATCH","path":"/referrals/{{referral_id}}/complete","query":[],"parameters":["referral_id"],"body":{"type":"object","fields":[{"name":"outcome","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_317","group":"Referrals","title":"Cancel Referral","method":"PATCH","path":"/referrals/{{referral_id}}/cancel","query":[],"parameters":["referral_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Only the referring hospital may withdraw a referral."},{"id":"op_318","group":"Consents","title":"Issue a Consent","method":"POST","path":"/consents","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"admission_id","type":"string","secret":false},{"name":"patient_id","type":"string","secret":false},{"name":"request_id","type":"string","secret":false},{"name":"prescription_id","type":"string","secret":false},{"name":"consent_type","type":"string","secret":false},{"name":"details","type":"string","secret":false},{"name":"signed_by_name","type":"string","secret":false},{"name":"signed_by_relation","type":"string","secret":false},{"name":"witness_name","type":"string","secret":false},{"name":"language","type":"string","secret":false},{"name":"allow_duplicate","type":"boolean","secret":false}]},"multipart":[],"description":"Creates the consent as PENDING with a serial (CNS-YYYYMMDD-NNNN) and a deadline for the signed scan.\n\nconsent_type: general | financial | procedure | chemotherapy | record_sharing | lama | tariff_change.\ndetails is required for procedure and chemotherapy — \"informed consent for [blank]\" is not informed consent.\nAttach it to an admission, an admission request, a prescription, or to the patient alone (financial consent is signed at the desk before a bed exists).\nIssuing does not touch S3, so admitting never waits on storage."},{"id":"op_319","group":"Consents","title":"List Consents","method":"GET","path":"/consents","query":["admission_id","status","consent_type","patient_id","prescription_id","outstanding","overdue","page","per_page"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"outstanding=true — still owes a signed copy (pending or verbal).\noverdue=true — past its deadline with nothing filed. This is the ward worklist, and what the daily chase job reads."},{"id":"op_320","group":"Consents","title":"Get Consent","method":"GET","path":"/consents/{{consent_id}}","query":[],"parameters":["consent_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Includes every document ever filed against it, with hashes."},{"id":"op_321","group":"Consents","title":"Download the Form (PDF)","method":"GET","path":"/consents/{{consent_id}}/form","query":[],"parameters":["consent_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Returns the printable PDF: hospital letterhead, patient and admission details, the versioned wording, signature blocks, and the serial with a QR so a batch of scans can be matched back.\n\nThe first call renders it and files it in S3; later calls return those exact bytes, because the paper in the patient's hand and the PDF on record have to be the same document.\nWorks without S3 configured — the form just is not kept."},{"id":"op_322","group":"Consents","title":"Upload the Signed Copy","method":"PUT","path":"/consents/{{consent_id}}/signature","query":[],"parameters":["consent_id"],"body":{"type":"object","fields":[]},"multipart":[{"name":"file","type":"file"},{"name":"data","type":"object","fields":[{"name":"signed_at","type":"string"},{"name":"witness_name","type":"string"},{"name":"note","type":"string"},{"name":"replace","type":"boolean"}]}],"description":"THE ONLY WAY A CONSENT BECOMES SIGNED. multipart/form-data only — a JSON body returns 400.\n\nSend `file` for one document, or `files` repeated for up to 5 pages, merged into one PDF in the order given (wards have phones, not scanners). Images are judged by their leading bytes, not the extension.\n\nsigned_at is when the paper was signed, read in the hospital's own timezone; uploaded_at is when it reached us. Both are kept.\n\nLimits: 10 MB per file, 40 megapixels per image, not password-protected.\nTo replace a scan already on file send replace=true with a note — the old one is superseded, never overwritten.\n503 means S3 is not configured; nothing is filed."},{"id":"op_323","group":"Consents","title":"Download the Signed Copy","method":"GET","path":"/consents/{{consent_id}}/document","query":[],"parameters":["consent_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Streams the scan. Add ?as=link for a presigned URL instead (expires in 120 seconds). Either way the access is written to the activity log — reading somebody's signed consent is access to their medical record."},{"id":"op_324","group":"Consents","title":"Signed Copy as a Link","method":"GET","path":"/consents/{{consent_id}}/document","query":["as"],"parameters":["consent_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_325","group":"Consents","title":"Record Verbal Consent","method":"POST","path":"/consents/{{consent_id}}/verbal","query":[],"parameters":["consent_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false},{"name":"witness_name","type":"string","secret":false},{"name":"verbal_witness_2","type":"string","secret":false}]},"multipart":[],"description":"The emergency stopgap: spoken consent attested by two DIFFERENT witnesses. The signed paper is still owed and the deadline still runs. A hospital can switch this off in settings."},{"id":"op_326","group":"Consents","title":"Withdraw Consent","method":"POST","path":"/consents/{{consent_id}}/withdraw","query":[],"parameters":["consent_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":"The patient revokes it. The signed document stays on file — what they signed and what they later revoked are both facts."},{"id":"op_327","group":"Consents","title":"Void Consent","method":"POST","path":"/consents/{{consent_id}}/void","query":[],"parameters":["consent_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":"For one issued in error, before anything was signed."},{"id":"op_328","group":"Consents","title":"Consent Bundle for the Case File","method":"GET","path":"/admissions/{{admission_id}}/consents/bundle","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Every consent document for the admission merged into one PDF. Consents with no signed copy are included as the blank form and named in the X-Consent-Warnings response header. Capped at 60 MB."},{"id":"op_329","group":"Consents","title":"Waive Missing Consents (admin)","method":"POST","path":"/admissions/{{admission_id}}/consents/waive","query":[],"parameters":["admission_id"],"body":{"type":"object","fields":[{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":"Hospital admin only. Lets a discharge through when a consent is past its deadline with nothing filed. The reason is recorded in the activity log — a gate with no way past it just gets worked around off the record."},{"id":"op_330","group":"Consent Templates","title":"Effective Wording","method":"GET","path":"/consent-templates","query":["effective","language"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"The one template that would actually be used for each consent type right now, with source: hospital | platform | built-in. This is what a settings screen shows."},{"id":"op_331","group":"Consent Templates","title":"List All Versions","method":"GET","path":"/consent-templates","query":["consent_type","language","active_only"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"This hospital's own wording plus the platform defaults (hospital_id null) that seed.py loads."},{"id":"op_332","group":"Consent Templates","title":"Get Template","method":"GET","path":"/consent-templates/{{consent_template_id}}","query":[],"parameters":["consent_template_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Includes the full body blocks and the declaration."},{"id":"op_333","group":"Consent Templates","title":"Publish New Wording","method":"POST","path":"/consent-templates","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"consent_type","type":"string","secret":false},{"name":"language","type":"string","secret":false},{"name":"title","type":"string","secret":false},{"name":"body","type":"array","item":{"type":"object","fields":[{"name":"heading","type":"string","secret":false},{"name":"text","type":"string","secret":false}]}},{"name":"declaration","type":"string","secret":false}]},"multipart":[],"description":"Never edits in place — writes the NEXT version and retires the previous one. Each consent records the template id and version it was issued against, so a consent signed in March still renders the March wording however much has been published since.\n\nNOTE: the {{...}} markers in the body above are CONSENT FORM placeholders, filled by the server when the PDF is rendered. Postman leaves undefined variables alone, so they reach the API intact - but do not define signatory, hospital_name, doctor_name or patient_name as Postman variables, or they will be substituted away before the template is saved.\n\nPlaceholders available: {{hospital_name}} {{patient_name}} {{patient_number}} {{age}} {{sex}} {{signatory}} {{relation}} {{witness}} {{details}} {{admission_number}} {{ward}} {{bed}} {{bed_class}} {{daily_rate}} {{estimated_cost}} {{billed_so_far}} {{doctor_name}} {{department}} {{to_hospital}} {{serial}} {{today}}. A placeholder with no value prints as a blank line to fill in."},{"id":"op_334","group":"Consent Templates","title":"Retire a Version","method":"PATCH","path":"/consent-templates/{{consent_template_id}}/retire","query":[],"parameters":["consent_template_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Stops issuing this wording; consents already issued against it are untouched. Platform defaults cannot be retired — publish your own wording instead, which takes precedence."},{"id":"op_335","group":"Reports · IPD","title":"IPD Overview","method":"GET","path":"/reports/ipd/overview","query":["from","to","hospital_id"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Census, occupancy, ALOS, turnover, readmission, mortality, LAMA, amount billed, revenue per occupied bed-day and outstanding dues."},{"id":"op_336","group":"Reports · IPD","title":"Occupancy","method":"GET","path":"/reports/ipd/occupancy","query":["from","to"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Daily midnight census and occupancy %, peak, day-care cases, and current beds by ward and bed class.\nDay-care stays have no midnight, so they are counted separately rather than lost."},{"id":"op_337","group":"Reports · IPD","title":"Admissions & Outcomes","method":"GET","path":"/reports/ipd/admissions","query":["from","to"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Volumes per day, split by type, source, payer, department and doctor, with average and median length of stay, discharge outcomes, readmissions and MLC cases."},{"id":"op_338","group":"Reports · IPD","title":"Revenue","method":"GET","path":"/reports/ipd/revenue","query":["from","to"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Billed, split into bed-days, packages, procedures, pharmacy and lab; by payer; settled from receipts and insurers; written off; collected after discharge; dues outstanding now."},{"id":"op_339","group":"Reports · IPD","title":"Insurance","method":"GET","path":"/reports/ipd/insurance","query":["from","to"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Claims by status, claimed vs settled, settlement ratio, average days to settle, pre-auth approval ratio, all by insurer."},{"id":"op_340","group":"Reports · IPD","title":"Referrals","method":"GET","path":"/reports/ipd/referrals","query":["from","to"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Referrals sent and received, transfers to and from group hospitals, and how many admission requests became admissions."},{"id":"op_341","group":"Medicines","title":"List Medicines","method":"GET","path":"/medicines","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_342","group":"Medicines","title":"Medicines Autocomplete","method":"GET","path":"/medicines/autocomplete","query":["q","limit"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_343","group":"Medicines","title":"Medicine Forms","method":"GET","path":"/medicines/forms","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_344","group":"Medicines","title":"Medicine Categories","method":"GET","path":"/medicines/categories","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_345","group":"Medicines","title":"Create Medicine (brand + generic)","method":"POST","path":"/medicines","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"name","type":"string","secret":false},{"name":"generic_name","type":"string","secret":false},{"name":"form","type":"string","secret":false},{"name":"category","type":"string","secret":false},{"name":"strength","type":"string","secret":false},{"name":"unit","type":"string","secret":false},{"name":"manufacturer","type":"string","secret":false}]},"multipart":[],"description":"generic_name is MANDATORY - the molecule is what identifies the drug clinically.\nname (brand / trade name) is OPTIONAL.\n\nResponses carry a read-only display_name: the brand when there is one, otherwise the molecule. Use it anywhere you need a single name to render."},{"id":"op_346","group":"Medicines","title":"Create Medicine (generic only)","method":"POST","path":"/medicines","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"generic_name","type":"string","secret":false},{"name":"form","type":"string","secret":false},{"name":"category","type":"string","secret":false},{"name":"strength","type":"string","secret":false},{"name":"unit","type":"string","secret":false}]},"multipart":[],"description":"No brand name - the common case for a drug that is prescribed and dispensed generically.\n\nname comes back null and display_name resolves to the molecule, so autocomplete labels, prescriptions and low-stock alerts all still read correctly."},{"id":"op_347","group":"Medicines","title":"Get Medicine","method":"GET","path":"/medicines/{{medicine_id}}","query":[],"parameters":["medicine_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_348","group":"Medicines","title":"Update Medicine","method":"PUT","path":"/medicines/{{medicine_id}}","query":[],"parameters":["medicine_id"],"body":{"type":"object","fields":[{"name":"manufacturer","type":"string","secret":false}]},"multipart":[],"description":"generic_name may be changed but never cleared (400). name may be cleared to turn a branded entry into a generic one."},{"id":"op_349","group":"Medicines","title":"Delete Medicine","method":"DELETE","path":"/medicines/{{medicine_id}}","query":[],"parameters":["medicine_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_350","group":"Stock","title":"Stock Summary (per medicine)","method":"GET","path":"/stock","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_351","group":"Stock","title":"Get Medicine Stock (batches FEFO)","method":"GET","path":"/stock/medicine/{{medicine_id}}","query":[],"parameters":["medicine_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_352","group":"Stock","title":"Receive New Batch","method":"POST","path":"/stock/receive","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"medicine_id","type":"string","secret":false},{"name":"batch_number","type":"string","secret":false},{"name":"quantity","type":"number","secret":false},{"name":"expiry_date","type":"string","secret":false},{"name":"unit_cost","type":"number","secret":false},{"name":"selling_price","type":"number","secret":false},{"name":"supplier_name","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_353","group":"Stock","title":"Get Batch","method":"GET","path":"/stock/batches/{{batch_id}}","query":[],"parameters":["batch_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_354","group":"Stock","title":"Adjust Batch (+/-)","method":"PATCH","path":"/stock/batches/{{batch_id}}/adjust","query":[],"parameters":["batch_id"],"body":{"type":"object","fields":[{"name":"delta","type":"number","secret":false},{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_355","group":"Stock","title":"Discard Batch (expired/damaged)","method":"PATCH","path":"/stock/batches/{{batch_id}}/discard","query":[],"parameters":["batch_id"],"body":{"type":"object","fields":[{"name":"transaction_type","type":"string","secret":false},{"name":"reason","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_356","group":"Stock","title":"Stock Transactions (audit log)","method":"GET","path":"/stock/transactions","query":["medicine_id","transaction_type"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_357","group":"Stock","title":"Low Stock","method":"GET","path":"/stock/low-stock","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_358","group":"Stock","title":"Expiring Batches","method":"GET","path":"/stock/expiring","query":["days"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_359","group":"Stock","title":"List Reorder Configs","method":"GET","path":"/stock/reorder-config","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_360","group":"Stock","title":"Set Reorder Config","method":"PUT","path":"/stock/reorder-config/{{medicine_id}}","query":[],"parameters":["medicine_id"],"body":{"type":"object","fields":[{"name":"reorder_level","type":"number","secret":false},{"name":"reorder_quantity","type":"number","secret":false},{"name":"expiry_alert_days","type":"number","secret":false}]},"multipart":[],"description":""},{"id":"op_361","group":"Devices (FCM)","title":"Register Device Token","method":"POST","path":"/devices/tokens","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"fcm_token","type":"string","secret":true},{"name":"device_type","type":"string","secret":false},{"name":"device_name","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_362","group":"Devices (FCM)","title":"List My Devices","method":"GET","path":"/devices/tokens","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_363","group":"Devices (FCM)","title":"Deactivate Device","method":"DELETE","path":"/devices/tokens/{{device_token_id}}","query":[],"parameters":["device_token_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_364","group":"Devices (FCM)","title":"Deregister by Token Value","method":"POST","path":"/devices/tokens/deregister","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"fcm_token","type":"string","secret":true}]},"multipart":[],"description":""},{"id":"op_365","group":"Devices (FCM)","title":"Send Test Push","method":"POST","path":"/devices/tokens/test","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"title","type":"string","secret":false},{"name":"message","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_366","group":"Notifications","title":"List Notifications","method":"GET","path":"/notifications","query":["page","unread_only"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_367","group":"Notifications","title":"Unread Count","method":"GET","path":"/notifications/unread-count","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_368","group":"Notifications","title":"Mark as Read","method":"PATCH","path":"/notifications/{{notification_id}}/read","query":[],"parameters":["notification_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_369","group":"Notifications","title":"Mark All Read","method":"PATCH","path":"/notifications/read-all","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_370","group":"Notifications","title":"Delete Notification","method":"DELETE","path":"/notifications/{{notification_id}}","query":[],"parameters":["notification_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_371","group":"Notification Preferences","title":"Get Preferences","method":"GET","path":"/notification-preferences","query":[],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":""},{"id":"op_372","group":"Notification Preferences","title":"Update Preferences","method":"PUT","path":"/notification-preferences","query":[],"parameters":[],"body":{"type":"object","fields":[{"name":"push_notifications","type":"boolean","secret":false},{"name":"email_notifications","type":"boolean","secret":false},{"name":"appointment_alerts","type":"boolean","secret":false},{"name":"billing_alerts","type":"boolean","secret":false},{"name":"quiet_hours_start","type":"string","secret":false},{"name":"quiet_hours_end","type":"string","secret":false}]},"multipart":[],"description":""},{"id":"op_373","group":"Activity Logs","title":"List Activity Logs","method":"GET","path":"/activity-logs/","query":["page","per_page","entity_type","entity_id","actor_id","action","date_from","date_to"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Paginated list of activity logs for the current hospital. Requires hospital_admin or superadmin role. Superadmin without a hospital context must pass ?hospital_id=."},{"id":"op_374","group":"Activity Logs","title":"Entity History","method":"GET","path":"/activity-logs/entity/patient/{{patient_id}}","query":["page","per_page"],"parameters":["patient_id"],"body":{"type":"object","fields":[]},"multipart":[],"description":"Full change history for one specific record. Replace 'patient' and {{patient_id}} with the target entity_type and entity_id. Allowed entity_types: patient, doctor, appointment, prescription, lab_order, lab_test, bill, payment, stock_batch, reorder_config, user, hospital, department, medicine, hospital_setting, membership, aadhaar_kyc. Requires hospital_context (any authenticated staff role)."},{"id":"op_375","group":"Activity Logs","title":"Activity Summary (7-day)","method":"GET","path":"/activity-logs/summary","query":["days"],"parameters":[],"body":{"type":"object","fields":[]},"multipart":[],"description":"Returns total event count, breakdown by entity_type and action, and 10 most recent events for the given period. Requires hospital_admin or superadmin role."}]''',
) as List).cast<Map<String, dynamic>>();
